programs.sol:
"""Recognize user headers, document-opening labels, and Japanese manner words.

The user-role newline gets a small negative value. At document start, the
colon after 'Q' gets a large negative value, whereas the colon after 'Title'
gets a positive value. The spelling of the colon token matters: attached
blank lines weaken the Q response. Japanese 'そう' (so/that way), 'こう'
(this way), and 'どう' (how) have progressively smaller negative values.
Everything else is zero. This deliberately omits other lexical responses.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, before = 0, '', ''
    else:
        _, position, previous, before = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '\n' and previous == 'user':
        if before == '<|im_start|>':
            value = -0.35
        elif position == 1:
            value = -0.20
    elif position == 1 and previous == 'Q':
        if token == ':':
            value = -9.12
        elif token == ':\n\n':
            value = -6.54
    elif position == 1 and previous == 'Title' and token == ':':
        value = 4.89
    elif token == 'そう':
        value = -2.55
    elif token == 'こう':
        value = -0.71
    elif token == 'どう':
        value = -0.20
    return (doc, position + 1, token, previous), value

programs.haiku:
"""layers.1.mlp.down_proj:704, read as four concepts; every other position is predicted as 0.

1. The first token of each packed document (the first token after <|endoftext|>, or the
   row's first token): '#' +0.68; a capitalised word or a non-Latin letter +0.34;
   a '<' tag -0.23; other lowercase or punctuation starts 0.
2. A colon right after a document's opening one-word label: 'Title:' +4.9; 'Q:' or
   'Q:' then a blank line -6.5.
3. The newline that opens a user turn (the token after 'user' in the chat template): -0.34.
4. The second and later '··' tokens of a long dotted leader (five or more in a row): +2.46.

Values are the component's typical activations in these cases. The program does not
capture the diffuse, token-specific activity everywhere else, nor the Japanese
kanji-after-kana spikes, which average near zero."""

READS = ()

USER_NEWLINE = -0.34
DOT_RUN_VALUE = 2.46
DOT_RUN_LENGTH = 5


def first_token_value(tok):
    if tok == "#":
        return 0.68
    if tok[:1].isupper() or (tok[:1].isalpha() and ord(tok[0]) > 127):
        return 0.34
    if tok.startswith("<"):
        return -0.23
    return 0.0


def step(carry, prefix, upstream):
    run = carry or 0
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    value = 0.0
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        value = first_token_value(tok)
    elif len(prefix) == 2 or prefix.document_ids[-2] != prefix.document_ids[-3]:
        if tok == ":" and prev == "Title":
            value = 4.9
        elif tok in (":", ":\n\n") and prev == "Q":
            value = -6.5
    if tok == "\n" and prev == "user":
        value = USER_NEWLINE
    if tok == "··":
        if run >= DOT_RUN_LENGTH:
            value = DOT_RUN_VALUE
        run += 1
    else:
        run = 0
    return run, value

programs.sol:
"""Predict abbreviation-like periods and middle-dot separators.

A period after a capitalized word plus initial, or after a spaced initial,
is strong. Line-start initials and compact dotted acronyms are weaker.
Known abbreviations and rare short Latin forms also respond. Ordinary stops
stay near zero.
Middle dots respond after Han, kana, or Hangul text; other tokens stay at zero.
Only a short text suffix is carried, resetting at document boundaries.
"""
import regex as re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

TITLES = set('mr mrs ms dr'.split())
OTHER_TITLES = set('prof rev hon st col gen capt lt maj supt pres'.split())
REFERENCES = set(
    'fig figs eq eqs sec secs sect ch chap vol vols pp para paras '
    'art arts no nos pat app ct cir civ dist supp ref refs ed eds '
    'doc stat hist med vet op cit'.split()
)
MONTHS = set('jan feb mar apr jun jul aug sep sept oct nov dec'.split())
UNITS = set('lb lbs oz qt qts pt pts ft min hr hrs'.split())
OTHER = set('etc vs cf ca approx dept est inc ltd co corp ave blvd rd sr jr'.split())


@lru_cache(maxsize=4096)
def frequency(word):
    return zipf_frequency(word, 'en')


def period_value(text):
    match = re.search(r'([^\W\d_]+)$', text)
    if not match:
        return 0.05
    word = match[0]
    low = word.lower()
    before = text[:-len(word)]
    line_start = not before.split('\n')[-1].strip()
    if len(word) == 1:
        if word.isupper():
            if line_start:
                return 0.35
            if re.search(r'\b\p{Lu}\p{Ll}+[ \t]+$', before):
                return 1.4
            if re.search(r'\p{L}\.[ \t]*$', before):
                return 0.78 if before.endswith('.') else 1.28
            return 0.85
        return 0.24 if line_start else 0.46
    if low in TITLES:
        return 0.18
    if low == 'al' and re.search(r'\bet[ \t]+al$', text, re.I):
        return 0.63
    if low in REFERENCES:
        if word.isupper():
            return 0.42
        return 1.0 if word.istitle() and len(word) >= 3 else 0.65
    if low in OTHER_TITLES or low in MONTHS:
        return 0.8
    if low in UNITS or low in OTHER:
        return 0.55
    # A rare short Latin form is another possible abbreviation.
    if 2 <= len(word) <= 4 and word.isascii() and not word.isupper():
        if frequency(low) < 3.7:
            return 0.6
    return -0.01


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = b'' if carry is None or carry[0] != doc else carry[1]
    current = prefix.token_bytes[-1]
    text = previous.decode('utf-8', errors='ignore')
    s = current.decode('utf-8', errors='ignore')
    value = 0.0
    if s == '.':
        value = period_value(text)
    elif s == '.,':
        value = 0.65 * period_value(text)
    elif s in {'·', '・', '･'}:
        if re.search(r'\p{Script=Han}$', text):
            value = 2.65 if s == '·' else 0.8
        elif re.search(r'[\p{Script=Katakana}\p{Script=Hiragana}'
                       r'\p{Script=Hangul}ー]$', text):
            value = 1.0
    return (doc, (previous + current)[-180:]), float(value)

"""Approximate a local signal for expressions specifying a place or setting.
Locating terms fire directly. Prepositions, especially 'in', get stronger
after spatial words, institutions and birth/residence language. Recent place
vocabulary, capitalization and dates supply context. WordNet supplies word
senses and inflection; a few multilingual location cues are lexical.
This leaves token-specific and richer contextual variation unexplained.
The bounded history resets at document boundaries.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

# Ordinary semantic word groups, shared across inflected forms.
GROUPS = {
    'located': set("""
        base headquarter locate situate
    """.split()),
    'life': set("""
        arrive born come die go grow live move raise reside settle stay
        travel visit
    """.split()),
    'address': set("""
        address coordinate latitude location longitude postal postcode zip
    """.split()),
    'relation': set("""
        above across adjacent along anywhere around back below beside
        between border bottom boundary center centre corner distance east
        eastern edge elsewhere end everywhere front heart here inside middle
        nearby north northeastern northern northwestern outside outskirts
        part proximity side south southeastern southern southwestern there
        top west western where wherever
    """.split()),
    'place_label': set("""
        area district locality location place position proximity region site
        spot venue vicinity zone
    """.split()),
    'built_environment': set("""
        architecture avenue bridge building highway road route street tower
    """.split()),
}

PREPOSITIONS = {
    "at": 0.73226,
    "near": 2.19531
}

@lru_cache(None)
def roots(word):
    return frozenset((word, *wordnet.base_forms(word)))


@lru_cache(None)
def ontology(word, group):
    kinds = {
        'spatial': ('location', 'facility', 'structure', 'body of water',
                    'geological formation', 'road'),
        'institution': ('organization', 'building'),
    }
    return any(wordnet.is_a(word, k) for k in kinds[group])


def belongs(word, group):
    if group in {'spatial', 'institution'}:
        return ontology(word, group)
    return not roots(word).isdisjoint(GROUPS[group])


@lru_cache(None)
def categories(word):
    return wordnet.categories(word) if word.isalpha() else frozenset()


@lru_cache(None)
def lexical_value(token):
    word = token.strip()
    low = word.lower()
    value = PREPOSITIONS.get(low, 0.0)
    value += 0.02275 * belongs(low, 'spatial')
    value += 0.47322 * belongs(low, 'address')
    value += 0.42977 * belongs(low, 'place_label')
    value += 0.59714 * belongs(low, 'built_environment')
    if low in {'located', 'situated', 'overlooking'}:
        value += 2.19003
    if low in {'nearby', 'beside', 'adjacent', 'proximity'}:
        value += 0.78246
    if low in {'km', 'kilometer', 'kilometers', 'kilometre',
                         'kilometres', 'mile', 'miles'}:
        value += 0.81362
    if low in {'в', 'во', 'на'}:
        value += 0.28448
    if any(c in word for c in ('在', '位于', '位於', '这里', '這裡',
                                      'そこ', 'ここ', '県', '市', '町')):
        value += 0.26691
    if word in {'位于', '位於', '所在地', '坐落', '地址'}:
        value += 1.71643
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    low = token.strip().lower()
    value = lexical_value(token)
    if low in {'on', 'at', 'to', 'of', 'along', 'in'}:
        words = re.findall(r'[A-Za-z]+', history[-160:])
        last = words[-1].lower() if words else ''
        geography = 0.0
        if low in {'in', 'on', 'along'}:
            geography = sum(
                any(belongs(w.lower(), g)
                    for g in ('spatial', 'relation', 'located'))
                for w in words[-24:]
            ) / 8
        if low == 'in':
            value += 0.51364 * geography
            value += 3.38828 * (belongs(last, 'located'))
            value += 0.73521 * (any(belongs(w.lower(), 'life') for w in words[-8:]))
            value += 0.9067 * (sum(w[:1].isupper() for w in words[-8:]) / 8)
            value += 0.43999 * (belongs(last, 'spatial'))
            value += 2.48964 * (last in {'born', 'birth', 'birthplace'})
            value += 0.53096 * (belongs(last, 'institution'))
            value -= 0.26013 * (not token[:1].isspace())
            value += 0.35511 * ('noun.time' in categories(last))
            value -= 0.20706 * ('noun.communication' in categories(last))
            value -= 0.24827 * (token.strip()[:1].isupper())
            value += 0.34052 * (bool(re.search(r'\d{4}', history[-40:])))
        elif low == 'of':
            value += 0.29561 * (belongs(last, 'spatial'))
        elif low == 'on':
            value += 0.46704 * geography
        elif low == 'at':
            value -= 0.63612 * (not token[:1].isspace())
        elif low == 'to':
            value += 0.18109 * ('verb.motion' in categories(last))
            value += 0.81063 * (bool(re.search(r'\b\d{4}[^A-Za-z0-9]*$', history)))
        elif low == 'along':
            value += 0.86626 * geography
    return (doc, (history + token)[-180:]), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:708 - a "research-literature claim" detector (negative-going).

What it does: this component goes clearly negative on the word that carries a claim from the
scientific literature, in review-style prose:
  - "it has been [shown] to be ...", "was [found] to", "is [unclear]", "is [believed]":
    a finding or belief participle right after has/have/had been, or a copula;
  - "[studies] have shown", "[several studies]", "recent [research]": the research-literature
    noun, strongest after a recency/quantity word, and the auxiliary that follows it;
  - the citation markers "][" and "[@" in numbered references;
  - a weaker, graded set of review-register words (widely, commonly, example, years, ...).
Everywhere else it sits near zero (small, diffuse noise that no simple rule captures).

The values are the average activation seen in each context on training rows (in activation
units, negative = the component is pushing against the claim-introducing context).
It reads only the current token and the two before it, so it is a left-to-right rule.
"""

READS = ()

# Participles that report a finding or a belief: "has been shown", "was found", "is believed".
FINDING = {
    "shown", "found", "reported", "proven", "understood", "believed", "investigated",
    "recognized", "hypothesized", "speculated", "linked", "discovered", "demonstrated",
    "suggested", "observed", "documented", "known", "thought", "considered", "used",
    "described", "associated", "implicated", "debated", "unclear", "clear", "investigating",
    "criticized", "uncertain", "unknown", "studied", "emerged", "attracted", "identified",
    "accepted", "established",
}
# Nouns for the research literature and its debates.
LITERATURE = {
    "studies", "study", "research", "researchers", "literature", "investigations",
    "investigation", "evidence", "debate", "hypothesis", "consensus", "controversies",
    "authors", "popularity", "attention", "interest",
}
# Words that mark a recent or general body of work: "recent studies", "several studies".
QUANTITY = {
    "recent", "recently", "several", "numerous", "previous", "many", "various", "much",
    "substantial", "considerable", "of", "these", "few",
}
# Auxiliaries and copulas: "has been", "is not yet", "are".
AUX = {"been", "have", "has", "had", "is", "are", "was", "were", "be", "not", "yet", "fully"}
# Hedges and generalisers common in review prose.
HEDGES = {
    "widely", "commonly", "growing", "increasing", "understanding", "example", "years",
    "decades", "often", "usually", "generally", "previously", "controversial", "emerging",
    "worldwide", "extensively", "been", "recent",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    n = len(prefix)
    same1 = n > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    same2 = n > 2 and prefix.document_ids[-3] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same1 else ""
    prev2 = prefix.token_strings[-3].strip().lower() if same2 else ""
    if prefix.token_strings[-1] in {"][", "[@"}:
        return carry, -0.9
    if word in FINDING and prev in AUX and prev2 in {"been", "has", "have", "had", "it"}:
        return carry, -2.0
    if word == "to" and prev in FINDING and prev2 in AUX:
        return carry, -0.8
    if word in LITERATURE and prev in QUANTITY:
        return carry, -2.4
    if word in {"have", "has"} and prev in LITERATURE:
        return carry, -2.4
    if word in FINDING:
        return carry, -0.3
    if word in LITERATURE:
        return carry, -0.5
    if word in HEDGES:
        return carry, -0.3
    return carry, 0.0

programs.sol:
"""Sparse document-opening responses, not a general semantic classifier.

Large negative responses mark a leading comment-only line, HTML declaration,
carriage returns, and certain two-token number or metadata openings. Smaller
positive responses mark time/place question openers and decorative headers.
All rules reset at document boundaries; most text receives zero.
"""
READS = ()


def opening_word(text):
    word = text.strip()
    # The time and place question adverbs have especially strong onset effects.
    if word.lower() in {'when', 'where'}:
        value = 3.13 if word.lower() == 'when' else 1.98
        value -= 0.64 * word.islower()
        value -= 0.80 * text.startswith(' ')
        return value
    if word == 'Как':                 # Russian "how"
        return 2.22
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, opening = 0, '', ''
    else:
        _, position, previous, opening = carry
        position += 1

    value = 0.0
    if position == 0:
        opening = text
        if text == '//\n':
            value = -79.65
        elif text == '<!':
            value = -24.88
        elif text == '\r':
            value = -32.59
        elif text == ' .':
            value = 3.21
        elif text == '[\n':
            value = 1.57
        elif text.startswith('/*') and set(text[1:]) == {'*'}:
            value = 2.1 if len(text) > 10 else 0.8
        elif len(text) > 8 and set(text) == {'-'}:
            value = 2.2
        else:
            value = opening_word(text)
    elif opening == '\r' and text == '\r':
        value = -32.59
    elif position == 1:
        if previous == '1' and text == '2':
            value = -16.19
        elif previous == '{' and text == '[':
            value = -38.72
        elif previous == 'Posted' and text == ' on':
            value = -17.87
        elif previous == 'Title' and text == ':':
            value = -2.02
    elif position == 2 and opening == '1' and previous == text == '2':
        value = -4.09

    # Preserve only an unbroken initial run of carriage returns.
    if opening == '\r' and text != '\r':
        opening = ''
    return (doc, position, text, opening), value

"""Sparse responses to familiar formatting and programming continuations.

The strongest rules recognize document-initial `Title:`, `See also`,
Java declarations, and documentation tags. Other rules recognize shell
options/subcommands and one- or five-space tokens beginning a line,
including lines encoded with a literal backslash-n. Unmatched text is zero.
Only the previous token and a short text tail are retained per document.
"""
import re

READS = ()

SHELL_COMMAND = re.compile(
    r'\b(cat|sed|grep|rg|python\d*|node|git|go|pip\d*|ssh[\w-]*|'
    r'cargo|npm|npx|rm|ls|find|curl|wget|head|tail|psql|gcc|bash|'
    r'sh|tar|chmod|docker|make|pytest)\b'
)
GIT_ACTIONS = {
    'status', 'diff', 'checkout', 'restore', 'add', 'commit',
    'reset', 'show', 'log', 'clone', 'ls', 'config', 'stash',
}
BUILD_ACTIONS = {'run', 'build', 'test', 'install', 'uninstall', 'update', 'fix'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    before = previous.strip()
    value = 0.0

    if tail == 'Title' and token == ':':
        value = 30.9
    elif before.lower() == 'see':
        if token == ' also':
            value = 7.0 if previous == 'See' else 4.8
        elif token == ' below':
            value = 1.9
    elif before == 'public':
        if token == ' class':
            value = 6.1 if previous == 'public' else 2.6
        elif token == ' static':
            value = 1.5
        elif token == ' interface':
            value = 3.5 if previous == 'public' else 1.0
    elif token in (' ', '     ') and (
        tail.endswith('\n') or tail.endswith('\\n')
    ):
        if token == ' ':
            value = 1.2 if tail.endswith('\\n') else 0.8
        else:
            value = 0.33
    elif token == ' ' and previous.endswith(("('", '("', 'f\'', 'f"')):
        value = 1.2
    elif previous.endswith('@'):
        if token == 'param':
            value = 5.5 if tail.endswith('/** @') else 1.4
        elif token == 'type':
            value = 3.3
        elif token == 'author':
            value = 2.6
        elif token == 'mock':
            value = -3.9
    elif previous == ' <':
        if token in ('iostream', 'string', 'vector'):
            value = 3.0
        elif token in ('param', 'typeparam'):
            value = 2.2
    elif previous in (' -', ' --') and token.isascii() and token.isalpha():
        # A nearby command distinguishes options from algebraic subtraction.
        if SHELL_COMMAND.search(tail):
            value = 1.5 if previous == ' -' else 0.85
    elif before == 'git' and word in GIT_ACTIONS:
        value = 1.5
    elif before in ('go', 'cargo', 'npm', 'apt', 'pip', 'pip3', '-get'):
        if token.startswith(' ') and word in BUILD_ACTIONS:
            value = 1.2 if before == 'go' else 2.0

    return (doc, token, (tail + token)[-160:]), float(value)

"""Approximate the first split of a vowel-initial word.

A one- or two-letter vowel-led first chunk gates the response. After a
single letter, chunks without a/e/i/o/u in transliteration are positive;
some vowel-bearing chunks are negative. Short Latin/Cyrillic vowel-led
chunks after a two-letter prefix are negative. Case, script, and repeated
consonants adjust the size. Other positions receive -0.002. This is an
orthographic approximation, not a model of lexical exceptions.
"""
from anyascii import anyascii
from functools import lru_cache
READS = ()
LATIN_VOWELS = frozenset('aeiou')
VOWELS = LATIN_VOWELS | frozenset('аеёиоуыэюя')
VOWEL_CARRIERS = frozenset('اأإآอ')

@lru_cache(maxsize=16384)
def shape(s):
    letters = ''.join(c for c in s if c.isalpha())
    roman = anyascii(letters).lower()
    onset = letters[:1].lower()
    initial_vowel = onset in VOWELS or roman[:1] in LATIN_VOWELS
    initial_vowel |= onset in VOWEL_CARRIERS
    count = sum(c in LATIN_VOWELS for c in roman)
    return letters, roman, initial_vowel, count


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        p, word_start = '', False
    else:
        _, p, word_start = carry
    a, _, vowel, prior_vowels = shape(p)
    b, br, _, vowels = shape(s)
    value = -0.002
    if word_start and vowel and len(a) <= 2 and s[:1].isalpha():
        if (len(a) == 2 and prior_vowels == 1
                and b[:1].lower() in VOWELS):
            if len(b) <= 2:
                if b.isupper():
                    value = -1.1
                elif a.istitle():
                    value = -0.8
                else:
                    value = -0.58
            elif len(b) == 3:
                value = -0.5 if b.isupper() else -0.2
        elif len(a) == 1:
            if vowels == 0:
                if not p.isascii() or not s.isascii():
                    value = 0.45
                elif b.isupper() and p[:1].isalpha():
                    value = 0.85
                elif len(b) >= 2 and len(set(b.lower())) == 1:
                    value = 0.55
                else:
                    value = 0.08
            elif b.istitle() and a.lower() == 'i':
                value = -0.85
            elif br[:1] not in LATIN_VOWELS and s.isascii():
                value = -0.3 if len(b) <= 5 else -0.08
    new_start = not s[:1].isalpha() or not p[-1:].isalpha()
    return (doc, s, new_start), value

"""Recognize words that introduce names, and periods that finish abbreviations.

The strongest cues are personal honorifics, Mount/Mt and named Operations.
Titles and prefixes have different typical strengths. Capitals matter: 'Ms'
is a personal title, but 'ms' is usually a unit or code. A period after an
honorific is much stronger than a period after an initial or citation.
Capitalized words already before an ambiguous title/place prefix weaken it,
except for conventional compounds such as Prime Minister and Major General.
The state tracks only the last words and token, resetting at document edges.
"""
import regex as re
import calendar

READS = ()

# Personal titles, ranks and forms of address, grouped by response strength.
TITLE_GROUPS = (
    (11.5, 'mme'),
    (7.0, 'rabbi uncle'),
    (6.0, 'ms messrs colonel madame madam'),
    (5.0, 'captain sir miss reverend monsieur admiral'),
    (4.0, 'mr mrs professor lieutenant sister viscount senator '
          'baroness aunt grandma grandpa'),
    (3.5, 'dr drs saint frau archbishop'),
    (3.0, 'lord father bishop queen governor inspector coach pastor mayor '
          'general councillor'),
    (2.5, 'king count countess minister judge justice lady herr sri commander'),
    (2.0, 'president doctor prince princess emperor empress pope duke duchess'),
    (1.5, 'baron ambassador master premier mother chef comrade'),
    (1.0, 'chief speaker secretary major cardinal'),
    (0.6, 'representative officer commissioner'),
)
