                    value *= 0.5
        elif low in RANKS:
            value = RANKS[low] if current.istitle() else 0.15
            if low == 'gen' and before.lower() in {
                'maj', 'major', 'lt', 'lieutenant', 'brigadier'
            }:
                value = 6.0
        elif low == 'st':
            value = 1.1 if current.istitle() else 0.0
        elif low in PLACES and current.istitle():
            value = PLACES[low]
            if low not in {'mount', 'mt'} and before[:1].isupper():
                if before.lower() not in FUNCTION_WORDS:
                    value *= 0.2
        elif low == 'operation' and current.istitle():
            value = 5.0 if s.startswith(' ') and not last.isspace() else 1.0
            if before.lower() in {'as', 'during', 'by', 'via', 'and', 'when'}:
                value = 12.0
            if '（' in s or last.endswith('（'):
                value = 12.0
        elif low in PREFIXES and (current.istitle() or current in {'USS', 'RAF'}):
            value = PREFIXES[low]
