        # The interpunct separates names transliterated into Chinese.
        value = 2.5 if re.search(r'\p{Han}', last) else 0.4
    return (doc, word, previous, s), float(value)

"""A sparse spelling predictor, not a general language understanding rule.

更 (more/change) and eng/äng fragments get negative values. Short acute-e
syllables get positive values in Hungarian-looking text, including their
following within-word fragments. Function words and ő/ű identify Hungarian;
the cue fades at word boundaries and resets at document separators.
"""
import re
import unicodedata

READS = ()
HUNGARIAN_FUNCTION_WORDS = {
    'az', 'egy', 'és', 'hogy', 'nem', 'vagy', 'mert', 'csak', 'már',
    'volt', 'pedig', 'után', 'előtt', 'között', 'kell', 'minden',
}


def vowels(s):
    return [c for c in s if unicodedata.normalize('NFD', c)[0] in 'aeiou']


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if not s:
        return carry, 0.0
    old_doc, word, language = carry if carry else (None, '', 0.0)
    if old_doc != doc:
        word, language = '', 0.0
    if s.startswith('<|'):
        word, language = '', 0.0
    before = word if s and s[0].isalpha() else ''
    for part in re.findall(r'[^\W\d_]+|[\W\d_]+', s.lower()):
        if part[0].isalpha():
            word = (word + part)[-64:]
            if any(c in part for c in 'őű'):
                language = 3.0
        else:
            language *= 0.99
            if word in HUNGARIAN_FUNCTION_WORDS:
                language = min(3.0, language + 1.5)
            word = ''
    state = (doc, word, language)
    t = s.strip().lower()
    value = 0.0
    if t == '更':
        value = -3.5
    elif '更' in t:
        value = -1.8
    elif t == '生' and before.endswith('更'):
        value = -4.5
    elif t == 'eng':
        value = -0.35 if s[0].isspace() else -2.0
    elif t == 'äng':
        value = -1.9
    elif (len(t) <= 4 and s[0].isalpha()
          and ('eng' in before[-2:] + t[:2])):
        value = -4.0
    elif t.isalpha() and len(t) <= 4 and language >= 0.5:
        prior_vowels = vowels(before)
        current_vowels = vowels(t)
        if 'é' in t and len(current_vowels) == 1:
            if not (t == 'és' and not before):
                value = 4.7 if not prior_vowels else 2.2
                # Voiceless labials beside acute e amplify the first syllable.
                if not prior_vowels and any(
                        pair in (before + t) for pair in ('fé', 'pé', 'ép', 'éf')):
                    value = 8.5
        elif before and prior_vowels and prior_vowels[-1] == 'é':
            if not current_vowels:
                value = 3.5
            elif len(current_vowels) == 1:
                value = 1.8
    if not value and before.endswith('eng') and t == 'ue' and s[0].isalpha():
        value = -5.0
    return state, value

