from functools import lru_cache
import unicodedata
import regex
import wordnet
from wordfreq import zipf_frequency
import cedict

READS = ()

CURRENT = {
    'code_segment': 0.179,
    'think_open': -2.071,
    'all_caps': -0.073,
    'log_status': 0.579,
    'response_tag': -0.596,
    'noun.cognition': 0.036,
    'tool_open': 0.71,
    'preposition': -0.041,
    'space_start': 0.036,
    'message_end': 0.266,
    'very_high_frequency': -0.03,
    'message_start': -0.213,
}

PREVIOUS = {
    'very_high_frequency': -0.048,
    'one_letter': -0.046,
    'message_end': 0.333,
    'punctuation': -0.035,
    'digit': -0.026,
    'pronoun': 0.04,
}

TRANSITIONS = [
    ('capitalized', 'capitalized', 0.208),
    ('noun', 'moderate_frequency', 0.054),
    ('noun', 'adjective_suffix', 0.117),
    ('han', 'han', 0.077),
    ('noun.group', 'noun', 0.071),
    ('noun', 'high_frequency', 0.031),
    ('noun.artifact', 'noun', 0.052),
    ('noun.substance', 'capitalized', -0.069),
    ('noun.person', 'capitalized', 0.072),
    ('adjective', 'preposition', -0.062),
    ('noun', 'determiner', -0.035),
]

FUNCTION_WORDS = {
    'determiner': set(
        'the a an this that these those each every some any no another'.split()
    ),
    'pronoun': set(
        'i you he she it we they me him us them'.split()
    ),
    'preposition': set(
        ('of to in on at for from with by as about into over under '
         'through between').split()
    ),
}

@lru_cache(maxsize=32768)
def properties(token):
    word = token.strip()
    lower = word.lower()
    letters = bool(word) and word.isascii() and word.isalpha()
    result = set()
    for name, words in FUNCTION_WORDS.items():
        if lower in words:
            result.add(name)
    if letters:
        poses = wordnet.parts_of_speech(lower)
        result.update(poses)
        result.update(wordnet.categories(lower))
        # Zipf frequency is the log10 frequency per billion English words.
        frequency = zipf_frequency(lower, 'en')
        bands = [('moderate_frequency', 4, 5),
                 ('high_frequency', 5, 6),
                 ('very_high_frequency', 6, 10)]
        for name, lo, hi in bands:
            if lo <= frequency < hi:
                result.add(name)
    if token.startswith(' '):
        result.add('space_start')
    if word.isdigit():
        result.add('digit')
    if bool(word) and all(unicodedata.category(c)[0] in 'PS' for c in word):
        result.add('punctuation')
    if letters and word[0].isupper():
        result.add('capitalized')
    if letters and word.isupper():
        result.add('all_caps')
    if letters and len(word) == 1:
        result.add('one_letter')
    if bool(regex.search(r'\p{Script=Han}', word)):
        result.add('han')
    if bool(regex.fullmatch(r'[._/-][A-Za-z][A-Za-z_]*', word)):
        result.add('code_segment')
    if word in {
        'PASS', 'FAIL', 'RUN', 'ERROR', 'WARN', 'WARNING',
        'INFO', 'DEBUG', 'SUCCESS', 'OK',
    }:
        result.add('log_status')
    if letters and lower.endswith(
        ('ic', 'ical', 'al', 'ous', 'ive', 'able', 'ible', 'ary')
    ):
        result.add('adjective_suffix')
    if word == '<think>':
        result.add('think_open')
    if word == '<tool_call>':
        result.add('tool_open')
    if word in {'<tool_response>', '</tool_response>'}:
        result.add('response_tag')
    if word == '<|im_start|>':
        result.add('message_start')
    if word == '<|im_end|>':
        result.add('message_end')
    return frozenset(result)

@lru_cache(maxsize=65536)
def predict(previous, current):
    left, right = properties(previous), properties(current)
    value = sum(CURRENT.get(k, 0.0) for k in right)
    value += sum(PREVIOUS.get(k, 0.0) for k in left)
    for current_class, previous_class, offset in TRANSITIONS:
        if current_class in right and previous_class in left:
            value += offset
    if (regex.search(r'\p{Script=Han}', previous)
            and regex.search(r'\p{Script=Han}', current)
            and cedict.glosses(previous.strip() + current.strip())):
        value += 0.13
    return float(value)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    return (document, token), predict(previous, token)

"""A sparse, partial predictor from spellings and document openings.

Its main negatives are acute S and short oa/oe word pieces after an o-ending
piece. The trailing letter-run length distinguishes co|ars from val|o|are.
Additional rules cover a few Japanese/Korean spellings, unfinished Unicode
letters and document-opening code syntax. Uncovered responses are left at zero.
"""
from functools import lru_cache
from anyascii import anyascii
import regex

READS = ()
TYPE_NAMES = frozenset(('int', 'char', 'string', 'float',
                        'double', 'bool', 'void'))
INTEGER_WIDTHS = frozenset(('long', 'short', 'byte'))
OPENING_SYNTAX = {
    '//\n': 7.58,
    '<!': 4.37,
    '<|im_start|>': 0.175,
    'public': 2.0,
    'private': 2.5,
    'protected': 0.77,
    'boolean': 1.42,
}
# Values after a short (at most two letters) versus a longer word beginning.
OA_PIECES = {
    'ar': (-4.07, -0.82),
    'are': (-6.67, -0.47),
    'ars': (-7.38, -2.47),
    'as': (-1.24, -0.28),
    'ase': (-5.15, -0.50),
}

@lru_cache(maxsize=40000)
def roman(text):
    return anyascii(text).lower()


def response(n, previous, current, previous_bytes, b, letters, initial_cr):
    if current == '\r' and initial_cr:
        return 4.04
    if n == 0:
        if current in TYPE_NAMES:
            return 2.92
        if current in INTEGER_WIDTHS:
            return 2.0
        if current in OPENING_SYNTAX:
            return OPENING_SYNTAX[current]
        if current.startswith('#'):
            return -0.64
        if current.isascii() and current.isdecimal():
            return -0.26
    if n == 1 and previous == '1' and current == '2':
        return 2.34

    p, c = roman(previous), current.lower()
    if c.strip() == 'ś':
        if p.endswith('o'):
            return -5.01
        return -1.27 if p.endswith('y') else -2.88
    if c == 'ů' and p.strip() == 'pr':
        return -2.88
    if n and len(p.strip()) <= 5:
        if p.endswith('o'):
            if c in OA_PIECES:
                short, internal = OA_PIECES[c]
                return short if letters <= 2 else internal
            if c in ('arse', 'arser', 'ari', 'ary'):
                return -2.25 if letters <= 2 else -0.40
            if c.startswith('ash'):
                return -5.0
            if c.startswith('resh'):
                return -3.12
            if c == 'er':
                return -1.18
            if c == 'ra':
                return -0.69
            if not c.isascii() and roman(c) in ('r', 'ra'):
                return -0.58
        if p.endswith('a') and c.startswith('ars'):
            return -1.21

    if current == '彼':
        return 1.12
    if previous == '彼' and current == '女':
        return 2.94
    if previous.endswith(('お', 'ご')):
        if current == '手':
            return -2.59
        if previous.endswith('ご') and current == '案':
            return -4.96
        if regex.match(r'[\p{Hiragana}\p{Han}]', current):
            return -0.37
    if previous.strip() == '이' and current == '어':
        return 5.82

    # A space followed by the first two bytes of a three-byte character.
    joined = previous_bytes + b
    if previous_bytes.startswith(b' ') and b and len(joined) == 3:
        if 0x80 <= b[0] <= 0xbf:
            if 0xea <= joined[1] <= 0xed:
                return 0.78
            if joined[1:3] == b'\xe1\x9a':
                return 2.65
    if current and current.strip('\u00a0') == '':
        return -0.054
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n, previous, previous_bytes, letters, initial_cr = 0, '', b'', 0, True
    else:
        _, n, previous, previous_bytes, letters, initial_cr = carry
    current, b = prefix.token_strings[-1], prefix.token_bytes[-1]
    value = response(n, previous, current, previous_bytes, b, letters, initial_cr)
    tail = regex.search(r'\p{L}+$', current)
    if tail:
        letters = letters + len(current) if tail.start() == 0 else len(tail[0])
    else:
        letters = 0
    carry = (doc, n + 1, current, b, min(letters, 3),
             initial_cr and current == '\r')
    return carry, value

