        if prev in PREPOSITIONS | COPULAS or prev.endswith("'s"):
            return -1.8 if word == 'where' else -0.5
        if word == 'where' and capital:
            return -0.5
    if word in {'however', 'whatever'} and capital:
        return 0.0 if word == 'however' else -2.2
    if word == 'que':
        if attached or capital:
            return 0.05
        if prev in {'lo', 'los', 'las', 'o', 'os', 'as', 'el', 'al', 'ao', 'ce'}:
