"""Wh-words and relative pronouns that open a relative or free-relative clause.

Component layers.1.mlp.down_proj:720 goes negative on words that introduce a clause
standing in for a noun phrase, in English and in other languages:

- "those who", "all that", "all who", "lo que", "los que", "al que", "ce qui",
  "tout ce qui", "كل من": a relative pronoun right after a quantifier or determiner.
  These are the strongest cases (about -4 to -5).
- "is what", "do what", "to what", "of what", "from what": "what" after a verb,
  copula or preposition, meaning "the thing that" (about -3.5).
- "whatever", "whoever", "chi", "wer", "ما" (what), "من" (who): free relatives in
  other forms, about -2 to -6.
- "what" after "know", "see", "ask" (embedded questions) is weaker (about -1), and
  "what" opening a question or clause after punctuation is weaker still (about -0.8).
- "how", "why", "where", "than" (weaker after "less"), and "as" after "much",
  "exactly", "far", "not", "long" (as much as, as far as) are mildly negative.

Plain "that", "which", "who" after a noun or comma, and "as" in most other uses stay
near zero. Everything else is zero.

The program is a small tiered rule: it looks at the current word and the word just
before it, and returns a value for the word's role in that frame.
"""

READS = ()

# Relative pronouns, negative when a quantifier or determiner comes right before them.
RELATIVE = {"who", "whom", "whoever", "que", "qui", "quien", "quienes", "chi", "wer", "من"}
# Quantifiers and determiners that set up a free relative: "all that", "those who", "lo que".
STRONG = {"all", "those", "these", "lo", "los", "las", "al", "el", "ce", "tout", "كل"}
# Weaker set-ups: "one who", "someone who", "anyone who".
MILD = {"one", "everyone", "anyone", "someone"}
# Pronouns and quantifiers that give a weaker "that" ("them that", "much that").
WEAK = {"them", "him", "me", "they", "much", "such", "any", "ones"}
# Verbs and prepositions after which "what" is a free relative ("is what", "to what").
FREE_HEAD = {"is", "was", "do", "does", "to", "of", "from", "with", "for", "in", "at", "on",
             "about", "and", "'s", "just", "say"}
# Verbs after which "what" is an embedded question ("know what").
ASK_VERBS = {"know", "see", "ask", "tell", "understand", "learn", "remember", "explain",
             "show", "wonder"}
# Adverbs in comparisons: "as much as", "as far as", "as long as".
AS_BEFORE = {"much", "far", "long", "exactly", "not", "just", "only"}
# Punctuation or document start: a wh-word here is usually a question.
OPENERS = {"", ",", ".", "?", "!", ";", ":", '"', "(", "\n"}
# Other wh-words and their usual strength.
WH = {"how": -0.7, "why": -0.5, "where": -0.3, "than": -0.4, "whatever": -3.0, "ما": -2.0}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    value = 0.0
    if word in RELATIVE and prev in STRONG:
        value = -5.0
    elif word in RELATIVE and prev in MILD:
        value = -2.5
    elif word == "that" and prev in STRONG:
        value = -4.5
    elif word == "that" and prev in MILD | WEAK:
        value = -1.0
    elif word == "what":
        if prev in OPENERS:
            value = -0.8
        elif prev in ASK_VERBS:
            value = -1.0
        elif prev in FREE_HEAD:
            value = -3.5
        else:
            value = -2.0
    elif word == "than" and prev == "less":
        value = -1.2
    elif word in WH:
        value = WH[word] * (0.4 if prev in OPENERS else 1.0)
    elif word == "as" and prev in AS_BEFORE:
        value = -1.5
    return carry, float(value)

programs.sol:
"""A small syntax-and-metadata detector.

Documentation openers (Javadoc, Doxygen, Rust, R) are positive, especially the
first line of a block. Documentation tags and Java-platform imports also
contribute, as do C++/Rust declaration markers. Web discussion labels and
document-initial 'Title:' are negative.
C standard-header suffixes are negative too. Small punctuation responses are
approximated; ordinary text defaults to zero. State resets between documents,
and literal backslash-n in quoted source is treated as a line break.
"""
import re

READS = ()
C_STANDARD_HEADERS = set('''
assert complex ctype errno fenv float inttypes iso646 limits locale math setjmp
signal stdalign stdarg stdatomic stdbool stddef stdint stdio stdlib stdnoreturn
string tgmath threads time uchar wchar wctype
'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, line, count, number, last_doc = '', '', 0, 0, -100
        diagnostic_until, pattern_until = -1, -1
    else:
        (_, before, line, count, number, last_doc,
         diagnostic_until, pattern_until) = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    value = 0.0
    # Permit indentation, source line numbers, and diff signs.
    line_start = re.fullmatch(r'[\s\d+.-]*', line) is not None

    # Recognize the constructs behind an indented vertical bar.
    if s == '-->' and line_start:
        diagnostic_until = number + 20
    if s in ('type', 'match', 'theorem') and line_start:
        pattern_until = number + 12

    if s == '/**':
        # A path ending in /** is a glob, not a documentation opener.
        path = line and not line[-1].isspace() and (
            line[-1].isalnum() or line[-1] in '/_.*}[]?')
        value = -0.8 if path else (4.5 if '\n' in token else 4.1)
        if count == 0:
            value = -0.2
    elif s == '///' and re.fullmatch(r'[\s\d+.:|-]*', line):
        value = 6.0 if number - last_doc > 1 else 3.3
        if '\n' in token:
            value = 1.3
        if count == 0:
            value = 0.2
        last_doc = number
    elif s == '//!' or (s == "#'" and line_start):
        value = 4.5
    elif s == '/*!':
        value = 3.2 if '\n' in token else 1.5
    elif s == 'summary' and '///' in line:
        value = 3.8
    elif (line + token).endswith(('begin-user-doc', 'end-user-doc')):
        value = 3.2
    elif s == 'brief' and before in ('@', '\\'):
        value = 2.5
    elif s == 'doc' and line.rstrip().endswith('#['):
        value = 4.5
    elif s == '#[':
        value = 2.0 if token.startswith(' ') else 1.2
    elif s in ('template', 'pub') and line_start and count > 0:
        value = 3.5 if s == 'template' else 1.4
    elif s == '*/':
        value = 0.3
    elif s and len(s) >= 2 and set(s) == {'#'}:
        value = 0.2
    elif s == '---':
        value = 0.7
    elif s in ('|', '|\\', '(|'):
        if s != '|':
            value = 1.0                  # Closure/alternation combinations
        elif line.rstrip().endswith('{-'):
            value = 10.0                 # Haskell documentation opener
        elif '-' in line and re.fullmatch(r'[-:|\s]+', line):
            value = 0.8 if '|' in line else 2.8
        elif line_start and number <= diagnostic_until:
            value = 1.6                  # Compiler diagnostic gutter
        elif line_start and number <= pattern_until:
            value = 4.0                  # Pattern match or union-type alternative
        else:
            value = 0.7 if line_start else 0.15
        if count == 0 and token == ' |':
            value = -1.1
    elif s == 'Tags' and before in ('Show', 'Hide'):
        value = -5.0 if before == 'Hide' else -5.8
        if before == 'Show' and line.lstrip().startswith('###'):
            value = -7.0
    elif s == 'Comment' and before in ('Author', 'Expert'):
        value = -14.7 if before == 'Author' else -10.0
    elif s == 'ed' and before == 'Comment':
        value = -6.6 if line.endswith('Author Comment') else -2.0
    elif s == 'Message' and before == 'Author':
        value = -6.8
    elif s == 'Starter' and before == 'Thread':
        value = -4.8
    elif s == 'permalink':
        value = -3.6
    elif token == ':' and count == 1 and before == 'Title':
        value = -9.96
    elif token == '.h':
        header = re.search(r'#\s*include\s*[<"]([^<>"/]+)$', line)
        value = (-2.8 if header[1] in C_STANDARD_HEADERS else -0.5) if header else 0.2
    elif s in ('java', 'javax', 'android') and before == 'import':
        value = 4.1 if s == 'android' else 1.4

    # Normalize escaped newlines too, so quoted code has sensible line state.
    joined = (line + token).replace('\\n', '\n')
    number += joined.count('\n')
    line = joined.rsplit('\n', 1)[-1][-120:]
    return (doc, s, line, count + 1, number, last_doc,
            diagnostic_until, pattern_until), value

"""Approximate a consonant-doubling feature.

Look for doubled consonants inside a token or across its left boundary, and
for repeated digits. Short, uncommon spelling fragments get larger values
than familiar whole words. Japanese small tsu and Arabic shadda are explicit
consonant-doubling signs. A small echo survives into a word's next fragment.
Document beginnings have a separate negative baseline.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
VOWELS = set('aeiouаеёиоуыэюя')
DOUBLING_SIGNS = set('っッ\u0651')

@lru_cache(maxsize=20000)
def frequency(word):
    return zipf_frequency(word, 'en')


def doubled_consonant(text):
    low = text.lower()
    return any(a == b and a.isalpha() and a not in VOWELS
               for a, b in zip(low, low[1:]))


def response(s, prev, word, first):
    if first:
        return -0.8
    if s == 'assistant':
        return 1.9
    if s in DOUBLING_SIGNS:
        return 4.3
    if '\u0651' in s:
        return 4.3
    if 'っ' in s or 'ッ' in s:
        return 1.2 if len(s) <= 2 else 0.15
    if s and prev and s[0] == prev[-1] and s[0].isdigit():
        return 1.28

    size = len(s.strip())
    cross = (s and prev and s[0].lower() == prev[-1].lower()
             and s[0].isalpha() and s[0].lower() not in VOWELS)
    if cross:
        # CamelCase word boundaries do not usually double a consonant.
        if s[0].isupper() and prev[-1].islower():
            return 0.08
        if size <= 2:
            if not s.isascii():
                return 1.5
            return 4.1 if len(word) <= 4 else 2.9
        return 1.9 if size == 3 else 0.83

    if doubled_consonant(s):
        familiar = frequency(word) > 4.86
        if size <= 4:
            if familiar:
                if s.strip().isupper():
                    return 1.4
                return 1.1 if s.strip().istitle() else 0.43
            return 2.5 if size <= 2 else 1.58 if size == 3 else 1.12
        f = frequency(s.strip())
        if size <= 6:
            if f > 4.06:
                return 0.52 if s.strip().istitle() else 0.29
            return 0.76 if size == 5 else 0.49
        return 0.37 if size == 7 and f <= 4.31 else 0.14

    continuation = (s and prev and s[0].isalpha()
                    and prev[-1].isalpha())
    if continuation and (doubled_consonant(prev)
                         or any(c in prev for c in DOUBLING_SIGNS)):
        if len(prev.strip()) <= 4:
            return 1.36 if size <= 2 and frequency(s) > 3.32 else 0.4
        return 0.15
    if '{{' in s:
        return 2.7
    return 0.007


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    prev, word = ('', '') if first else carry[1:]
    s = prefix.token_strings[-1]
    match = re.search(r'[^\W\d_]+$', word + s)
    word = match.group() if match else ''
    value = response(s, prev, word, first)
    return (doc, s, word[-100:]), value

"""An approximate expression-separator detector.

Positive pulses mark addition/subtraction following a completed operand and
commas near the start of a compact parenthesized argument list. Powers,
radicals and products strengthen arithmetic pulses. Nearby coordinate-geometry
words strengthen the first-comma pulse. Prose commas, hyphens and unary signs
are mostly quiet. Some non-English forms of 'in' give negative pulses.
A short text tail and unfinished brackets reset per document. Incomplete UTF-8
characters are carried to the next token, so split exponents remain readable.
"""
import re
import codecs
import unicodedata

READS = ()
EXPONENT_DIGITS = '⁰¹²³⁴⁵⁶⁷⁸⁹'


def greek_name(word):
    name = 'LAMDA' if word.lower() == 'lambda' else word.upper()
    try:
        unicodedata.lookup('GREEK SMALL LETTER ' + name)
        return True
    except KeyError:
        return False

IN_PREPOSITIONS = {
    'em': -.54,  # Portuguese
    'en': -.44,  # Spanish / French
    'в': -.43,  # Russian
    'در': -.43,  # Persian
}


def arithmetic(s, history, previous_token):
    q = s.strip()
    p = history.rstrip()
    last = p[-1:]
    if q.startswith((')', ']', '}')):
        return 1.0
    if not last or not (last.isalnum() or last in ')]}²³'):
        return -.07
    if previous_token.isspace():
        return -.05
    if p.endswith('()'):
        return .1
    line = history.rsplit('\n', 1)[-1]
    power = any(ch in EXPONENT_DIGITS + '^√∛∜' for ch in p[-12:])
    product = bool(re.search(
        r'[×*]|[0-9][a-zA-Z]|[0-9] (?:sin|cos|tan)', p[-14:]))
    equation = bool(re.search(
        r'[=^]|\\(?:frac|sqrt|left|right)', line))
    spaced = s.startswith(' ')
    previous = previous_token.strip()
    if power:
        if spaced:
            value = (1.44 if last.isdigit() else 1.10) + .25 * product
        else:
            value = .53 if '-' in q or '−' in q else .96
    elif equation:
        if spaced:
            value = (.93 if len(previous) <= 2 or greek_name(previous) else .14)
            value += .25 * product
        else:
            value = .57 if len(re.findall('[A-Za-z]{3,}', line)) <= 2 else .22
    elif spaced:
        single_letter = ((len(previous) == 1 and previous.isalpha())
                         or greek_name(previous))
        value = (.68 if single_letter else .10) + .65 * product
    else:
        word = re.search(r'\w+$', p)
        coordinate = word is not None and (
            word[0].lower() in {
                'x', 'y', 'z', 'ax', 'ay', 'bx', 'by', 'cx', 'cy'
            } or greek_name(word[0]))
        value = .44 if coordinate else (.14 if product else .01)
    return value * (.6 if q[-1:].isalpha() else 1.0)


def comma(history, stack, q):
    if not stack:
        return 0.0
    opening, before, segment, formal = stack[-1]
    compact = not re.search(r'\S\s+\S', segment.strip())
    count = segment.count(',')
    call = bool(re.search(r'[\w\]]$', before))
    if opening == '(' and not formal:
        if compact:
            if count == 0:
                letters = re.search('[A-Za-z_]', segment)
                value = 1.2 if not letters else (.88 if call else .42)
                geometry = re.search(
                    r'\b(?:coordinates?|points?|vectors?|vertex|vertices|'
                    r'centroid|midpoint)\b',
                    history, re.I)
