                    value = 1.65
            else:
                value = .3 if count == 1 else .08
        else:
            value = (.27 if call else .02) if count == 0 else 0.0
    elif opening == '[' and compact and count == 0:
        value = .35
    else:
        value = 0.0
    return value * (.6 if q[-1:].isalpha() else 1.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, stack, previous, pending = '', [], '', b''
    else:
        _, history, stack, previous, pending = carry
        stack = list(stack)
    raw = pending + prefix.token_bytes[-1]
    s, consumed = codecs.utf_8_decode(raw, 'replace', False)
    pending = raw[consumed:]
    q = s.strip()
    value = IN_PREPOSITIONS.get(q.lower(), 0.0) if s.startswith(' ') else 0.0
    if s == 'В':
        value = -.4
    if '\n' not in s:
        if re.fullmatch(r'''(?:["']|\(\))?,(?:[A-Za-z]|[-\\])?''', q):
            value = comma(history, stack, q)
        elif re.fullmatch(r'[)\]}]*[+−±-](?:[A-Za-z]|\\)?', q):
