    return (doc, history, stack[-30:], s, pending), float(value)

programs.haiku:
"""Plus and minus signs that join algebraic terms, such as 3x^3 + 5x or a^2 - b^2.

What it does (activation predicted at each token from the text so far):
- A spaced "+" or "-" (also after a non-breaking space) that follows a single-letter
  variable, a digit, a superscript, a closing bracket or brace gets a positive value.
  It grows with how algebraic the nearby text is (count of single-character math tokens
  and carets in the last ~20 tokens), and is larger after a superscript. Without a space,
  only a sign after a single-letter variable counts, at a reduced value.
- A sign after a closing quote (string concatenation in code, like "a" + b) is slightly negative.
- A comma inside brackets (argument lists, tuples such as (x, y)) is positive, more so after a digit.
- The words "en", "em" and Cyrillic "в" (Spanish, Portuguese, Russian for "in") are negative.
- A run of repeated middle dots (a dot leader) is positive; this is rare.
Everything else is 0. Predictions are in the component's activation units.
"""

READS = ()

MINUS = {"+", "-", "−", "–"}
SUPERSCRIPTS = set("²³⁴⁵⁶⁷⁸⁹⁰¹")
MATH_SYMBOLS = set("=+-^()") | SUPERSCRIPTS
IN_WORDS = {" en", " em", " En", "En", " в", " В", "В"}  # 'in' in Spanish, Portuguese, Russian


def is_math_token(tok):
    s = tok.strip()
    return len(s) == 1 and (s.isalnum() or s in MATH_SYMBOLS)


def is_term_end(s):
    """A single variable, digit or superscript, or a closing bracket or brace."""
    return (len(s) == 1 and (s.isalnum() or s in SUPERSCRIPTS)) or s in (")", "]", "}")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    if cur in IN_WORDS:
        return None, -0.4
    if cur.strip() and set(cur) <= set("·"):
        return None, 1.0
    if cur.strip() in MINUS and len(toks) >= 2:
        j = len(toks) - 2
        spaced = cur.startswith(" ") or " " in toks[j]
        while j > 0 and toks[j].strip() == "" and toks[j] != "\n":
            j -= 1
        prev = toks[j].strip()
        if prev.endswith('"') and not is_term_end(prev):
            return None, -0.25
        if not is_term_end(prev):
            return None, 0.0
        if not spaced and not (len(prev) == 1 and prev.isalpha()):
            return None, 0.0
        near = toks[max(0, len(toks) - 21):-1]
        density = sum(is_math_token(t) for t in toks[max(0, len(toks) - 17):-1])
        value = 0.3 + 0.07 * density
        if prev in SUPERSCRIPTS:
            value += 0.7
        if any("^" in t or "**" in t for t in near):
            value += 0.45
        if not spaced:
            value *= 0.7
        return None, value
    if cur.endswith(",") and ")" not in cur and "\n" not in cur:
        depth = 0
        for t in toks[-80:-1]:
            depth += t.count("(") - t.count(")")
        if depth >= 1:
            density = sum(is_math_token(t) for t in toks[max(0, len(toks) - 13):-1])
            value = 0.25 + 0.03 * density
            if toks[-2].strip().isdigit():
                value += 0.25
            return None, value
    return None, 0.0

programs.sol:
"""Approximate a sparse structured-text response, not general prose meaning.

Recognize document-description phrases (especially ``This preview shows``),
``This`` opening headings/comments, documentation tags and URLs, numbered
bracket labels, and short separator lines. Ordinal chapter/class labels give
negative responses. Small corrections cover source-file openings. Constants
are approximate training averages; heading responses fade with document age.
"""
import math
import re

READS = ()
DESCRIPTION_NOUNS = {
    'file', 'module', 'document', 'section', 'article', 'post', 'preview',
    'implementation', 'code', 'message', 'content', 'entry', 'chapter', 'handbook',
}
SOURCE_OPENERS = {'package': -1.78, 'using': 1.08,
                  'class': 1.53, 'function': 1.35}


def response(token, previous, before, history, age):
    word, pword = token.strip(), previous.strip()
    line = history.rsplit('\n', 1)[-1]
    last_line = history.rstrip().rsplit('\n', 1)[-1]
    fade = math.exp(-age / 180.0)

    if word in {'This', '>This'}:
        if age == 0:
            return -0.21 if token == 'This' else -0.77
        if word == '>This':
            return 1.1
