    ("This", " preview"): 5.0, (" preview", " shows"): 3.0,  # "This preview shows pages"
    ("Last", " edited"): 3.8,                              # "Last edited:"
    (" file", " contains"): 2.0,                           # "This file contains"
    ("<", "summary"): 1.4, ("</", "summary"): 1.1,         # XML doc tags
    ("<", "param"): 1.5, ("<", "font"): 2.6, ("\"><", "font"): 2.5,  # HTML / XML tags
    ("<", "DOCUMENT"): 2.5, ("<?", "php"): 0.9,
    ("://", "doc"): 2.4, ("://", "docs"): 1.1, ("-user", "-doc"): 1.4,
    (" shows", " pages"): 2.2,
    ("\n\n", "This"): 0.6,
}

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        # first token of a document (right after <|endoftext|>)
        if cur == "package":
            return None, -1.8   # the common "package com.x" opener
        if cur.isdigit():
            return None, 0.5
        if cur == "\t":
            return None, 3.7
        if cur == "<|im_start|>":
            return None, 0.5
        return None, 0.0
    prev = prefix.token_strings[-2]
    if cur.strip() == "]:" and (prev.strip().isdigit() or prev.strip() == "?"):
        return None, 2.7    # reference-list label "[1]:"
    if cur.strip() == "---" and prev.strip() in ("", "\n", ")"):
        return None, 1.5    # line of dashes (separator / diff header)
    return None, float(PHRASES.get((prev, cur), 0.0))

programs.sol:
"""Local structure in technical text, not a general semantic classifier.

The strongest positive rules mark later groups of dotted numbers, declaration
modifiers, and source/documentation references. Smaller rules recognize API
headings and tags, JSON arguments and separators. Most tokens predict zero.
The bounded text carry resets at document boundaries and also handles escaped
newlines in quoted code. Amplitudes are approximate training estimates.
"""
import re

READS = ()
ACCESS = {'public', 'private', 'protected'}
DECLARATIONS = {'static', 'const', 'export', 'pub', 'func', 'inline', 'var'}
TAGS = {'param', 'return', 'returns', 'constructor', 'classmethod', 'link'}
HEADINGS = {'Parameters', 'Arguments', 'Args', 'Returns', 'Return', 'Methods',
            'Usage', 'Summary', 'Description', 'Syntax', 'License'}
SOURCE = {'src', 'source', 'components', 'classes', 'index'}
LIBRARY = {'lib', 'pkg', 'dist', 'api', 'docs', 'pages', 'include'}


def response(s, tail, n):
    if n == 0:
        return -0.12 if s.isdigit() else -0.30
    tail = tail.replace('\\n', '\n').replace('\\t', '\t')
    word = s.strip()
    line = re.sub(r'^\s*\d+\s+', '', tail.rsplit('\n', 1)[-1])

    # First digit following a dot: separate versions from decimal fractions.
    if len(s) == 1 and s.isascii() and s.isdigit():
        m = re.search(r'(\d+(?:\.\d+)*)\.$', tail)
        if m:
            groups = m[1].split('.')
            before = tail[:m.start()]
            boundary = before[-1:]
            if len(groups) >= 2:
                return 0.87 if len(groups[0]) == 4 else 2.52
            version = boundary and (boundary in '/_vV>' or
                       boundary == '-' and before[-2:-1].isalnum())
            if version or re.search(r'(?i)(version|pkgver)[^\n]{0,20}$', before):
                return 1.28
            if 'PASS:' in tail or 'FAIL:' in tail or 'warnings in ' in tail:
                return 0.83
            return 0.10 if groups[0] == '0' else 0.28
        if n == 1 and tail == '.':
            return 1.30
    if s == '.':
        m = re.search(r'\d+\.(\d+)$', tail)
        if m and len(m[1]) <= 3:
            return 0.82
        if re.search(r'__\d+$', tail):
            return 0.43

    # Code declarations, including line-numbered and indented listings.
    if word in ACCESS and (not line.strip() or
                           line.rstrip().endswith(('{', ';', '}', ':', '`'))):
        return 1.43 if word == 'public' else 1.13
    if word in DECLARATIONS:
        if (not line.strip() or line.strip() in ACCESS or
            word in {'const', 'static'} and re.search(r'[;{}*`]', line)):
            return 1.36 if word == 'static' else 0.52
    if s in TAGS and tail.rstrip().endswith(('@', ':', '{@')):
        return 1.8 if s == 'link' else 0.66
    if word in {'Override', '@Override'}:
        return 0.76
    if s == ' {' and re.search(r'@(param|returns?)\s*$', tail):
        return 1.25
    if word == 'arguments' and tail.rstrip().endswith('"'):
        return 0.90

    # API documentation and conventional source-file references.
    if s == ' source' and tail.endswith('View'):
        return 3.5
    if word in HEADINGS and re.fullmatch(r'[\s*#/-]*', line):
        return 2.2 if word in {'Parameters', 'Arguments'} else 0.90
    if s in {'\n', '\n\n', ':', ':\n'} and line.strip() in HEADINGS:
        return 0.80
    if word.lower() == 'value' and tail.endswith(('Return', 'Return ')):
        return 2.0
    if s == ' `' and line.strip() in {'###', '####'}:
        return 3.0
    if s == '.md' and re.search(r'(?i)readme[^\s/]*$', tail):
        return 2.0 if line.strip().upper() == 'README' else 0.87
    if s == '.html':
        return 1.0
    if s.startswith('/') and word[1:] in SOURCE:
        return 1.12
    if word in {'src', 'index'}:
        return 0.43
    if s.startswith('/') and word[1:] in LIBRARY:
        return 0.35
    if s == ' also' and tail.endswith('See'):
        return 1.1
    if '¶' in s:
        return 1.7
    if re.fullmatch(r'\s*={5,}\s*', s):
        return 1.25 if s.startswith(' ') else 0.35
    if s in {'<tool_response>', '</tool_call>'}:
        return -0.13
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, n = '', 0
    else:
        _, tail, n = carry
    s = prefix.token_strings[-1]
    value = response(s, tail, n)
    return (doc, (tail + s)[-160:], n + 1), float(value)

programs.haiku:
"""Activation of one MLP down-projection feature in layer 1 of Qwen3-1.7B.

What it responds to, in plain terms:
  * the first digit of the third part of a software version number ("2.17.2", "v0.15.0"),
    strongly, and the first digit of the second part ("1.0") when the number follows a
    version-like cue (a name, "v", "/", "-", "__" as in "repo__1.0"), weakly otherwise;
  * access modifiers that open a code declaration: public, private, protected at the start
    of a line (Java/C#-style members), and "static" anywhere; the same words inline in prose
    do not fire;
  * other programming keywords (func, impl, const, var, interface, @Override);
  * source-tree path pieces and file types (/src, src, /lib, .md, .html, .ts);
  * API-documentation headings and parameter words (Arguments, Parameters, Returns, ...);
  * the "#" that starts an anchor right after an ".html" link;
  * a run of middle-dot filler characters, where it is strongly negative.
Everything else is predicted as 0. It is a short list of named rules, not a fitted model,
so it explains only part of the variance: the component is diffuse, and most of what is left
is a long tail of individual words. Values are the mean activations of each class.
"""
READS = ()

DIGITS = set("0123456789")
FILLER = "··"
MODIFIERS = {"public", "private", "protected", "pub"}
OTHER_CODE = {"static", "func", "impl", "const", "var", "interface", "Override", "@Override"}
PATH_WORDS = {"/src", "src", "/lib", "/pkg", "/api", "/index", "/latest", "/bin", "/components",
              "/docs", "/dist", "/reference", "README"}
FILE_TYPES = {".md", ".html", ".ts"}
DOC_WORDS = {"arguments", "Arguments", "Args", "Parameters", "Returns", "Usage", "Summary",
             "Documentation", "Synopsis", "Inputs", "API"}
VERSION_CUES = {"__", "v", "/", "-"}   # the token just before a version-like number


def starts_line(token):
    """True when the token before a word is a line break or indentation."""
    return "\n" in token or (token != "" and token.strip() == "")


def step(carry, prefix, upstream):
    raw_prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    tok = prefix.token_strings[-1].strip()
    prev = raw_prev.strip()
    # carry: (dots seen in the current run of digits and dots, token before that run)
    dots, cue = carry or (0, "")
    value = 0.0
    if tok == FILLER:
        value = -1.3
    elif tok in DIGITS and prev == ".":
        if dots >= 2:
            value = 1.7                      # third version part, e.g. the 2 in 2.17.2
        elif dots == 1:
            value = 1.1 if cue in VERSION_CUES else 0.2
    elif tok == "#" and raw_prev.endswith(".html"):
        value = 3.5                          # anchor in a link to an HTML page
    elif tok in MODIFIERS:
        value = 1.3 if starts_line(raw_prev) else 0.1
    elif tok in OTHER_CODE:
        value = 0.7
    elif tok in PATH_WORDS:
        value = 0.7
    elif tok in FILE_TYPES:
        value = 0.5
    elif tok in DOC_WORDS:
        value = 0.6
    if tok in DIGITS or tok == ".":
        starts_run = not (prev in DIGITS or prev == ".")
        carry = (dots + (tok == "."), prev if starts_run else cue)
    else:
        carry = (0, "")
    return carry, value

programs.sol:
"""A rough signal for setting a general frame: 'In ...', 'but in ...',
'in most ...', and descriptions of what is normal, typical, or real.

Clause openings, contrast words, and focus words strengthen prepositions.
Quantifiers distinguish broad statements ('most people') from superlatives
('the most') and questions ('how many'). Generic descriptions have their own
response. All rules use token text, with a short document-local text buffer.
"""
import re

READS = ()
CONTRAST = set('but because since while whereas although though unless'.split())
LINKS = set('that where when if so hence therefore thus'.split())
FOCUS = set('even especially particularly notably only also primarily mostly '
            'mainly predominantly chiefly equally not'.split())
PREPOSITIONS = set('in for on with by at to of from under over between among'.split())
COMMONNESS = set('common normal regular standard typical ordinary usual '
                 'conventional traditional classical classic'.split())
STRONG_DEFAULTS = set('typical ordinary conventional traditional'.split())
REALITY = set('real actual reality realistic practical'.split())
SCOPE = set('general particular specific certain current present previous '
            'modern future other'.split())
FREQUENCY = set('generally usually normally commonly typically often '
                'frequently rarely occasionally sometimes'.split())
OBSERVATION = set('used found shown applied observed seen known'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, prev, recent = carry
    s = prefix.token_strings[-1]
    w, p = s.strip().lower(), prev.strip().lower()
    cap = s.strip()[:1].isupper()
    spaced = s[:1].isspace()
    sentence = bool(re.search(r'[.!?。！？][\)\]\"”\']*\s*$', recent))
    paragraph = bool(re.search(r'\n\s*$', recent))
    frame = 0.0
    if (sentence or paragraph) and cap:
        frame = 1.0 if spaced or w in ('many', 'most', 'some') else 0.7
    elif re.search(r'[,，]\s*$', recent):
        frame = 0.35
        if re.search(r'(however|therefore|thus|similarly|alternatively|moreover|'
                     r'furthermore|indeed|example|instance|particular|contrast|'
                     r'general|case|words|wait)[,，]\s*$', recent, re.I):
            frame = 1.4
    elif re.search(r'[:;：；]\s*$', recent):
        frame = 0.55
    if p in CONTRAST:
        frame = max(frame, 1.45 if prev.strip()[:1].isupper() else 1.2)
    elif p in LINKS or p in FOCUS:
        frame = max(frame, 0.7)
    elif p in ('as', 'than', 'like', 'unlike'):
        frame = max(frame, 0.9)
    elif p in ('and', 'or'):
        frame = max(frame, 0.3)
    value = 0.0
    if w in ('in', 'for', 'with', 'on', 'at'):
        gain = {'in': 1.5, 'for': 0.8, 'with': 0.8, 'on': 0.45, 'at': 0.4}[w]
        value = gain * frame
        if frame == 0.35:  # an ordinary comma, not a discourse marker
            value *= 0.65
        if w == 'for' and sentence and cap and spaced:
            value = max(value, 0.95)
        if w in ('with', 'on') and p in OBSERVATION:
            value = max(value, 0.2)
        if w == 'in':
            value += 0.05
            if p in OBSERVATION:
                value = max(value, 1.4 if p in ('seen', 'observed', 'known')
                            else (0.4 if p == 'shown' else 0.8))
            if p in COMMONNESS:
                value = max(value, 2.5 if p == 'common' else 1.1)
    elif w in ('many', 'most', 'some'):
        frame = max(frame, 0.45 if p in PREPOSITIONS else 0.0)
        base, gain = {'many': (0.35, 1.25), 'most': (0.7, 1.8),
                      'some': (0.05, 1.25)}[w]
        value = base + gain * frame
        if p == 'in':
            value = {'many': 2.0, 'most': 3.7, 'some': 1.3}[w]
            if prev.strip() == 'In':
                value = {'many': 4.0, 'most': 6.0, 'some': 3.3}[w]
        if w == 'most' and p in ('the', 'at'):
            value = -0.1
        if w == 'many' and p in ('how', 'too', 'as', 'so', 'infinitely'):
            value = 0.05
        if p in ('like', 'unlike'):
            value = {'many': 3.5, 'most': 4.5, 'some': 2.6}[w]
    elif w == 'all':
        value = 0.5 if p == 'in' else 0.0
        if prev.strip() == 'In' or p in ('not', 'nearly', 'almost', 'virtually'):
            value = 1.5
    elif w in COMMONNESS:
        value = 1.3 if w in STRONG_DEFAULTS else 0.75
        if p == 'in':
            value = 2.0
        elif cap and not sentence:
            value = 0.3
    elif w in REALITY:
        value = 1.8 if p == 'in' else (0.2 if w == 'practical' else 0.5)
    elif w in SCOPE:
        value = 0.5 if p == 'in' else (0.35 if w in
                   ('general', 'current', 'modern', 'future') else 0.15)
    elif w in FREQUENCY:
        value = 1.3 if (sentence or paragraph) and cap else 0.15 + 0.5 * frame
        if w == 'sometimes':
            value = max(value, 0.75)
    elif w == 'according':
        value = 1.2 if p in CONTRAST or p in LINKS else (0.65 if cap else 0.05)
    elif w == 'of' and (p in ('lot', 'case', 'majority', 'much') or '%' in prev):
        value = 0.6
    elif w in ('a', 'an', 'the') and prev.strip() == 'In':
        value = 0.25
    elif w in ('в', 'во', 'bei'):
        value = (0.8 if cap or w == 'bei' else 0.4) if spaced or cap else 0.0
    elif w in ('en', 'dans', 'im', 'em', 'nel', 'nella'):
        value = 0.6 if sentence and cap else (0.12 if spaced else 0.0)
    elif w in ('los', 'las', 'les', 'gli', 'os', 'delle', 'della'):
        value = 0.7 if sentence and cap else (0.45 if spaced and not cap else 0.05)
    elif w in ('很多', '许多', '不少', '某些', '一些', '大多数', '多数', 'بعض'):
        value = 1.0
    return (doc, s, (recent + s)[-50:]), float(value)

programs.haiku:
"""Rule 5: the word that opens a generalising or framing phrase.

It fires on the opening word of a phrase that states a general rule or a case
qualifier: "In this case", "But in most cases", "For example", "Many people",
"regular use", "les/los/bei/в" (the same words in other languages). Strongest on
sentence-initial "In" (+ "In general", "In other words"), weaker on "in" after
a comma, "but", "even", "because". Near zero for "in" as a plain location
("located in", "in 2005") and on document starts.
"""

READS = ()

BREAK = {'.', '!', '?', ':', '\n', '"', ').', '."', '.\n', '\n\n', '.\n\n'}
CONJ = {'but', 'and', 'or', 'because', 'even', 'whereas', 'while', 'if', 'so', 'though',
        'however', 'then', 'also', 'maybe', 'as', 'when'}
QUANT = {'most', 'many', 'some', 'other', 'regular', 'normal', 'common', 'standard', 'real',
         'actual', 'general', 'current', 'typical', 'modern', 'several', 'few', 'all', 'usual',
         'ordinary', 'traditional', 'classical', 'certain', 'lot'}
FOREIGN = {'les', 'los', 'las', 'gli', 'bei', 'в', 'os', 'le', 'alle', 'у', 'при', 'В'}
CHINESE = {'其实', '不少', '某些', '很多', '实际上', '实际'}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, -0.15  # first token of a document
    before = prefix.token_strings[-2]
    prev = before.strip().lower()
    at_start = before in BREAK or before.endswith('\n')
    if word.lower() == 'in':
        if at_start:
            return carry, 1.2
        if prev in CONJ:
            return carry, 1.0
        if prev == ',':
            return carry, 0.6
        return carry, 0.1
    if word.lower() == 'for':
        return carry, 0.4 if (at_start or prev in CONJ) else 0.03
    if word.lower() in QUANT:
        return carry, 0.2 if prev in CONJ else 0.3
    if word in FOREIGN:
        return carry, 0.3
    if word in CHINESE:
        return carry, 1.5
    return carry, 0.0

programs.sol:
"""Recognize object-state declarations and updates in source code.

The strongest negative responses are indented instance receivers (self/this),
particularly near constructors, and private/protected class members before
method bodies. Deeper nesting and numbered source listings weaken the response.
Other text is mostly quiet. A short text tail supplies the code context; this is
not a parser and cannot distinguish every declaration from a method signature.
A smaller lexical response separates plural/reported studies from 'of/or study'
constructions, and responds negatively to the phrase 'study of'.
"""
import math
import re

READS = ()

RECEIVERS = {'self', 'this'}
ACCESS = {'private', 'protected'}
INTERESTING = RECEIVERS | ACCESS | {
    'final', 'static', 'public', 'super', 'construct', 'constructor',
    '$', '$_', '._', '->', 'readonly', 'slots', 'function', 'param', 'var',
    'study', 'studies',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
    if word == 'of' and re.search(r'\bstudy\s*$', text):
        value = -1.3
    elif word in INTERESTING:
        context = text.replace('\\n', '\n').replace('\\r', '\r')
        line = context.rsplit('\n', 1)[-1]
        numbered = bool(re.match(r'^\s*\d+[\t:]', line))
        line = re.sub(r'^\s*\d+[\t:]', '', line)
        leading = token[:len(token) - len(token.lstrip())]
        indent_text = line + leading
        start = not indent_text.strip()
        indent = len(indent_text.expandtabs(4))
        listing = 0.8 if numbered else 1.0
        definitions = list(re.finditer(r'\bdef\s+(\w+)\s*\(', context))
        last_def = definitions[-1] if definitions else None
        class_pos = context.rfind('class ')
        method_pos = -1
        for match in re.finditer(r'\)\s*(?:throws [\w, ]+)?\s*\{', context):
            method_pos = match.start()
        fields = method_pos < class_pos or (
            method_pos < 0 and 'return ' not in context
        )
        if word in {'study', 'studies'}:
            if word == 'studies':
                value = 0.7
            elif re.search(r'\b(?:of|or)\s*$', context):
                value = -2.7
            elif re.search(
                r'\b(?:a|the|this|our|present|previous|recent)\s*$',
                context, re.I,
            ):
                value = 0.5
            else:
                value = -0.35
        elif word in RECEIVERS:
            if start and indent > 0:
                if word == 'self':
                    if last_def:
                        distance = len(context) - last_def.start()
                        if last_def[1] == '__init__':
                            strength = 7 + 8 * math.exp(-distance / 200)
                        else:
                            strength = 1 + 4.5 * math.exp(-distance / 350)
                        if last_def[1].startswith('test_'):
                            strength = 0.9
                    else:
                        strength = 6.0
                    if '<?php' in context or '$this' in context:
                        strength = 1.0
                    if re.search(r'\b(?:fn|impl)\b', context) and not last_def:
                        strength = 0.8
                else:
                    constructor = re.search(
                        r'\b(?:constructor|__construct)\s*\(|'
                        r'\bfunction\s+[A-Z]\w*\s*\(|'
                        r'\b(?:public|private|protected)\s+[A-Z]\w*\s*\(',
                        context,
                    )
                    strength = 3.0
                    if constructor:
                        strength = 10.0
                    elif 'public ' in context:
                        strength = 7.0
                decay = 4 if word == 'self' else 8
                value = -strength * 2 ** (-abs(indent - 8) / decay) * listing
            elif word == 'self':
                code = re.search(r'[=(,]|\breturn\b', line)
                value = -0.3 if code else 0.65
            else:
                if re.fullmatch(r'\s*\$', line):
                    value = -3.0
                else:
                    code = re.search(r'[=(,]|\breturn\b', line)
                    value = -0.3 if code else 0.3
        elif word in ACCESS:
            if start and indent > 0:
                strength = 7.3 if word == 'private' else 5.5
                if not fields:
                    strength = 1.5
                style = 0.75 if '\t' in indent_text else 1.0
                value = -strength * 2 ** (-abs(indent - 4) / 3) * style * listing
            else:
                value = 0.2
        elif word == 'final':
            if re.search(r'\bprivate\s*$', line):
                declaration = re.match(r'^\s*private', line)
                value = -9.0 * listing if declaration else -3.0
            elif re.search(r'\bprivate\s+static\s*$', line):
                value = -3.6
            elif re.search(r'\bpublic\s+static\s*$', line):
                value = -1.8
            else:
                value = 0.1
        elif word == 'static':
            value = -0.9 if 'private' in line else -0.2
        elif word == 'public':
            value = -0.35 if start else 0.0
        elif word in {'construct', 'constructor'}:
            constructor = word == 'constructor' and start
            value = -4.5 if constructor or text.endswith('__') else 0.0
        elif word == 'super' and start:
            value = -3.0
        elif word == '._' and re.search(r'\bself$', line):
            value = -2.5 if last_def and last_def[1] == '__init__' else -0.8
        elif word == '->' and re.search(r'\bthis$', line):
            value = -2.0
        elif word == 'readonly' and re.search(r'\bprivate\s*$', line):
            value = -8.5
        elif word == 'slots' and text.endswith('__'):
            value = -6.0
        elif word == 'function' and re.search(
            r'\b(?:public|protected|private)\s*$', line
        ):
            value = 1.7
        elif word in {'param', 'var'} and text.endswith('@'):
            value = -1.1
        elif word in {'$', '$_'}:
            if word == '$_' and re.search(r'\bprotected\s*$', line):
                value = -7.0
            elif re.search(r'\b(?:private|protected)(?:\s+static)?\s*$', line):
                value = -6.0
            elif start:
                value = -1.0
    text = (text + token)[-3000:]
    if '<|endoftext|>' in token:
        text = text.rsplit('<|endoftext|>', 1)[-1]
    return (doc, text), value

"""A selective surface approximation for identifier separators.

Underscores are strongest after long or already segmented names, or in code.
Hyphens are strongest within path names; web-address dots and macro-call bangs
are treated separately.  Short TeX subscripts are suppressed.  Other tokens
are zero.  Histories decay over roughly 50 tokens and reset per document.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, '', 0., 0., 0.)
    _, run, code, slashes, dollars = carry
    match = re.search(r'[\w$]+$', run)
    word = match[0] if match else ''
    letters = any(c.isalpha() for c in word)
    path = '/' in run or bool(re.match(r'^[A-Za-z]:\\', run))
    snake = '_' in word
    math = ((dollars > .2 and len(word) <= 1)
            or re.search(r'\\[A-Za-z]+$', run))
    value = 0.

    if s == '_' or (len(s) > 1 and s[0] == '_' and s[1] in '.,(;'):
        if word and not math:
            if snake or len(word) > 8:
                value = .75
            elif word.islower() and code > 4:
                value = .5
            else:
                value = .1 if word.isupper() else .15
    elif s == '__' and word:
        value = .15 if path else .3
    elif s.startswith('__(') and word:
        value = .45
    elif (len(s) > 1 and s[0] == '_' and s[1].isupper()
          and not s[1:].isupper() and word):
        value = .25
    elif s == '-' and letters:
        if path:
            leaf = run.replace('\\', '/').rsplit('/', 1)[-1]
            value = .75 if '-' in leaf else .2 + .04 * min(slashes, 8)
        elif run.startswith('--'):
            value = .4
    elif s == '.':
        if word.lower() == 'www':
            value = 1.
        elif '://' in run:
            value = .16 if word.isdigit() else .65
        elif snake and code > 4:
            value = .2
    elif word and (s == '!' or s.startswith('!(')):
        value = .45 if s.startswith('!(') else (.25 if code > 4 else 0.)

    if first:
        value = 0.
    run = re.split(r'\s', run + s)[-1][-120:]
    code = .98 * code + sum(c in '_=(){}[];' for c in s)
    slashes = .98 * slashes + s.count('/')
    dollars = .98 * dollars + s.count('$')
    return (doc, run, code, slashes, dollars), float(value)

"""A rule approximation for name, literal, and absolute-path boundaries.

Positive responses mark quoted names, field/value separators and path openers.
Nearby naming words distinguish these from ordinary quotation and descriptive
strings. Chinese place-name endings have a separate response. Document starts
have a negative baseline; unrecognized text is zero. Numbers are rounded
training averages, not a table of token identities.
"""
import re

READS = ()
NAMING = re.compile(
    r'\b(?:name|named|called|entitled|dubbed|nicknamed|titled|title|alias)\b',
    re.I,
)
WORKS = re.compile(
    r'\b(?:book|novel|film|movie|album|song|poem|program|programme|series|'
    r'article|chapter|paper|play|musical|story|magazine|journal|newspaper|'
    r'label|brand|heading|filename|directory|path)\b', re.I,
)
NAME_FIELDS = {'name', 'title', 'id', 'alias'}
FILE_FIELDS = {'command', 'path', 'file', 'filename', 'url', 'src', 'href'}
NAMED_ARGUMENT = re.compile(
    r'(?:name|title|describe|test|label|path|route|join|open|load|require|'
    r'import|include)$', re.I,
)


def predict(text, token, first):
    s = token.strip()
    if first:
        if token.startswith('<|'):
            return -0.218
        return -0.41 if not s or s.isdigit() else -0.354

    # 州 is the Chinese prefecture/state suffix; zhou is its romanization.
    if s.endswith('州'):
        return 1.43 if len(s) == 1 else 0.62
    if s.lower() == 'zhou':
        return 1.1
    if s.lower() == 'hou' and text.lower().endswith('z'):
        return 2.0

    prior = text.rstrip()
    words = re.findall(r'[A-Za-z_]+', prior[-70:])
    last = words[-1].lower() if words else ''

    if '/' in s and not any(c.isalnum() for c in s):
        if '.' in s:
            return 0.11
        if '<' in s:
            return 0.05
        if s == ':/':
            return 1.29
        if s == '=/':
            return 1.67
        if s in ('[/', '{/', '>/', '!/', '(/'):
            return 0.78
        if s.endswith('/') and any(c in s for c in '\"\'`='):
            if '`' in s:
                return 0.74
            return 1.24 if token.startswith(' ') else 0.91
        if s == '/' and (token.startswith(' ') or prior.endswith(('"', "'", '`'))):
            if prior.endswith('directory:'):
                return 1.21
            if last in ('cd', 'file', 'interpreter', 'path'):
                return 0.82
            return 0.03 if prior[-1:].isdigit() or prior.endswith(')') else 0.32

    if s in ('":', "':", '\\":'):
        return 0.80 if last in NAME_FIELDS else 0.58 if last in FILE_FIELDS else 0.35
    if s == ':"':
        return 0.30
    if s == ':':
        if text.strip().lower() == 'title':
            return 3.58
        if last in NAME_FIELDS or last == 'namespace':
            return 0.36
        if re.search(r'(?:[,{]\s*|\n[ \t]+(?:\d+[ \t]+)?)[a-z_][A-Za-z_]*$', text[-100:]):
            return 0.23
        return 0.0

    if s.endswith('"') and set(s[:-1]) == {'\\'}:
        return 0.76 if prior.endswith('\\') else -0.012
    if s in ('《', '『', '「'):
        return 0.127
    if s in ('"', "'", '“', '‘', '„', '«', '`', '("', "('", '="', "='"):
        if re.search(r'["\']name["\']\s*:\s*$', prior, re.I):
            return 0.50
        if token.startswith('='):
            identifiers = NAME_FIELDS | FILE_FIELDS | {'class', 'type', 'value'}
            return 0.21 if last in identifiers else 0.08
        if NAMING.search(last):
            return 0.33
        if WORKS.search(' '.join(words[-3:])):
            return 0.21
        if s.startswith('('):
            if NAMED_ARGUMENT.search(prior):
                return 0.235
            return 0.09
        if prior.endswith((':', ',', '=', '>', '<', '[', '{')):
            if last in ('type', 'description', 'old_str', 'new_str', 'file_text'):
                return -0.14
            if last in NAME_FIELDS | FILE_FIELDS | {'class'}:
                return 0.53
            return 0.006
        if s == '`':
            return 0.022
        return -0.012 if s in ("'", '‘') else 0.075

    if token.startswith(' ') and s.lower() in ('called', 'named', 'dubbed', 'nicknamed'):
        return 0.248
    if token.startswith(' ') and s.lower() in ('titled', 'entitled'):
        return 0.615
    if s == 'No' and last in ('pat', 'patent'):
        return 0.54
    if s == 'git' and prior.endswith('diff --'):
        return 0.735
    if s == 'namespace':
        return 0.393
    if s == 'import':
        return -0.081
    if s == '_' and token.startswith(' '):
        return -0.154
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    text = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = predict(text, token, first)
    return (doc, (text + token)[-180:]), value

"""Sparse spelling rules for an n-syllable contrast.

Non and short n|on fragments are negative; space-prefixed nun and N|un
are positive. Smaller rules cover nu fragments, Cyrillic initial н,
Greek ν/Ν + vowels, and a document-initial Title: field. Boundaries and
case change the strengths. These are spelling rules, not a general
semantic negation detector; other lexical and byte-fragment effects
are deliberately left at zero.
"""
from anyascii import anyascii

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous, pos = ('', 0) if carry is None or carry[0] != doc else carry[1:]
    s = anyascii(token).lower().strip()
    word = s.lstrip('._/(-')
    value = 0.0

    # The non- prefix, not the unrelated word "none".
    if word == 'non':
        value = -0.65 if token.startswith(' ') else -1.5
        if token.strip().isupper():
            value *= 2.0
    elif word in ('nond', 'nons'):
        value = -5.6
    elif word == 'nun':
        value = 2.9 if token.startswith(' ') else 0.1
    elif word == 'nicht':
        value = -0.35
    elif word == 'niet':
        value = -1.0
    elif word in ('nu', 'nut', 'nuts', 'nude', 'nour'):
        value = 0.5 if token.startswith(' ') else 0.1
    if token.strip().lower() == 'nå':
        value = 2.6

    # Read a syllable split after n, but never across a space or document.
    p = previous.lower().rstrip()
    if p.endswith('n') and token and not token[0].isspace():
        isolated_n = p.strip() == 'n'
        if s.startswith('on') and len(s) <= 4 and s not in ('one', 'only'):
            if s in ('ond', 'ons', 'ong', 'ont'):
                value = -11.0 if isolated_n else -3.6
            else:
                value = -2.4
        elif s == 'un':
            value = 5.1 if previous.strip() == 'N' else 0.0
        elif s.startswith(('ub', 'unc', 'ur')):
            value = 1.2 if isolated_n else 0.08
        elif s.startswith(('icht', 'iet')):
            value = -0.8
        elif len(s) <= 3 and s.startswith(('im', 'iv')) and isolated_n:
            value = 2.3

    # Cyrillic n has a related vowel contrast. The ne- prefix is negative;
    # ni-/nu-/no- continuations and the pronoun endings -ей/-ём are positive.
    if previous in (' н', ' Н', 'Н') and token and not token[0].isspace():
        t = token.lower()
        if t in ('им', 'ими', 'ей', 'ём', 'его', 'их', 'её'):
            value = 2.6
        elif t[0] in 'иуо':
            value = -0.8 if t.startswith('он') else 1.3
        elif t[0] == 'а':
            value = 0.55
        elif t[0] == 'е':
            value = -0.35

    # Greek να is much stronger with a leading-space nu token than bare ν.
    if previous.strip() in ('ν', 'Ν') and token and all(
        ch in 'αεηιουωάέήίόύώ' for ch in token.lower()
    ):
        if previous.startswith(' '):
            value = 4.3 if token == 'α' else 1.5
        else:
            value = 3.1 if previous == 'Ν' and token.islower() else (
                0.35 if previous == 'ν' and token == 'α' else 0.0
            )
    if pos == 1 and previous == 'Title' and token == ':':
        value = -5.146
    return (doc, token, pos + 1), value

programs.haiku:
"""Weak prediction of the word-internal 'on' / 'op' fragments (no leading space) as a
negative activation, and of the English prefix ' non' more weakly. The scale is kept small
because the component is sparse and these rules do not track it reliably on held-out text."""

READS = ()

WORD_INTERNAL_ON = {"on", "op", "ope"}
NON_PREFIX = {" non", " Non", "Non", " NONE", "NONE"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in WORD_INTERNAL_ON:
        return carry, -0.15
    if tok in NON_PREFIX:
        return carry, -0.05
    return carry, 0.0

"""Everyday-life words of 衣食住行 (clothing, food, housing, transport), as whole tokens.

Layer-1 MLP component 736 writes into the residual stream when the current token is one
of a small set of everyday Chinese nouns and verbs, each standing alone as a token:

- clothing 衣 (garment) and its words: 衣服, 内衣, 白衣, 穿衣, 衣物, 外套, 衫, 袍, 裤, 鞋,
  袜, and the verbs 穿 (wear), 身穿, 穿着, 穿上, and 披 (cloak). The strongest group;
  the bare 衣 is the single largest driver;
- housing 屋 (house, room) and 屋子, 房子, 房屋, 豪宅, 别墅, 住 (live);
- food 食 (food) and 吃 (eat), 饭 (rice meal);
- transport 舟 (boat), 骑 (ride), 车子 (vehicle).

Compounds that merely contain the character (屋顶 roof, 食品 food product, 穿越 time travel,
舟山 a place name) do not fire, so the match is on the whole token. Everything else is 0.
The predicted value is the word's average activation in the training data.
"""

READS = ()

CLOTHING = {
    "衣": 5.8, "内衣": 3.8, "白衣": 3.2, "穿衣": 3.0, "衣服": 2.7, "披": 3.3,
    "穿": 1.9, "身穿": 2.4, "穿着": 1.6, "穿上": 0.9, "袍": 1.7, "衫": 1.7,
    "衣物": 1.6, "外套": 1.4, "裤": 1.2, "裤子": 1.3, "鞋": 0.8, "袜": 0.8,
}
HOUSING = {"屋": 3.3, "屋子": 2.5, "房子": 1.1, "房屋": 0.9, "豪宅": 0.7, "别墅": 0.5, "住": 0.3}
FOOD = {"食": 1.1, "吃": 0.7, "饭": 0.5}
TRANSPORT = {"舟": 2.5, "骑": 0.9, "车子": 0.8}
WORDS = {**CLOTHING, **HOUSING, **FOOD, **TRANSPORT}


def step(carry, prefix, upstream):
    # The newest token, decoded alone: a whole word matches, a longer word containing it does not.
    return carry, WORDS.get(prefix.token_strings[-1], 0.0)

programs.sol:
"""Local continuations of the round letter o (or an alphanumeric zero).

Digits after o/O receive positive pulses, strongest for 2, 3 and 4.
The cue survives chemical-formula separators. A zero after a letter is a
weaker cue. In contrast, i-initial word continuations after o are negative,
especially oi-st, oi-m and oi-nk. An apostrophe after a lone o is positive.
The same contrast is approximated for Cyrillic and Greek o-i sequences.
Carbon dioxide receives its own chemical-compound pulse. History resets
at document boundaries. Common complete English words ending in o are
weaker cues than fragments; the prepositions to and into are excluded.
"""
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# Response sizes for the ten digits, in their ordinary numerical order.
DIGIT_PULSE = (0.8, 3.0, 5.6, 6.8, 6.1, 4.4, 2.7, 2.5, 1.9, 1.8)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, previous = '', ''
    else:
        _, before, previous = carry
    text = prefix.token_strings[-1]
    value = 0.0
    if len(text) == 1 and text in '0123456789':
        strength = 0.0
        if previous.endswith(('o', 'O')):
            strength = o_strength(previous)
        elif previous == '0':
            if before[-1:].isalpha():
                strength = 0.35 if before[-1:].isupper() else 0.18
            elif before.isspace():
                strength = 0.06
        elif before.endswith('O') and len(before.strip()) <= 3:
            if previous.isspace() or previous in ('~', '$_'):
                strength = 1.0
            elif previous == '(':
                strength = 0.5
            elif previous in ('-', '^'):
                strength = 0.3
        elif before.endswith('o') and previous in ('-', '('):
            strength = 0.25
        value = 1.2 * strength * DIGIT_PULSE[int(text)]
    elif previous.endswith(('o', 'O')):
        continuation = text
        if continuation.startswith('i'):
            if continuation.startswith('ink') or continuation == 'ik':
                value = -12.0
            elif continuation.startswith('ist'):
                value = -6.5
            elif continuation.startswith(('im', 'int')):
                value = -4.5
            elif continuation.startswith(('ix', 'iv', 'ic', 'ig')):
                value = -1.8
            else:
                value = -0.3
        elif previous.strip().lower() == 'o' and text[:1] in ("'", '’'):
            value = 4.0
        value *= o_strength(previous)
    elif previous in ("'", '\u2019') and before.strip().lower() == 'o':
        if text.strip() == 'clock':
            value = 6.0
    # Cyrillic o followed by i.
    elif previous.endswith('о') and text.startswith('и'):
        value = -2.0
    elif previous.strip().lower() == 'carbon' and text.strip() == 'dioxide':
        value = 5.0

    # Greek spelling often puts o, i, and the following consonant in
    # separate tokens. Normalize accents and repair split UTF-8 characters.
    plain_previous = unaccent(previous)
    plain_text = unaccent(text)
    if plain_text == 'ι':
        t = prefix.position
        recent = recent_greek(prefix, doc, t + 1)
        if recent.endswith('οι'):
            value = -5.0 if '\ufffd' in previous else -1.2
    elif plain_previous == 'ι' and plain_text[:1].isalpha():
        t = prefix.position
        if recent_greek(prefix, doc, t).endswith('οι'):
            if plain_text[:1] in 'αεηιουω':
                value = -1.2
            else:
                value = -13.0 if plain_text.startswith('κ') else -5.5
    return (doc, previous, text), value


def unaccent(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text)
                   if not unicodedata.combining(c))


@lru_cache(maxsize=4096)
def o_strength(token):
    """Short fragments are stronger cues than ordinary complete words."""
    word = token.strip().lower()
    if word in ('to', 'into') and token[:1].isspace():
        return 0.0
    strength = min(1.0, 4 / max(1, len(word)))
    if len(word) > 3 and zipf_frequency(word, 'en') > 4:
        strength *= 0.15
    return strength


def recent_greek(prefix, doc, stop):
    start = max(0, stop - 4)
    while start < stop and prefix.document_ids[start] != doc:
        start += 1
    raw = b''.join(prefix.token_bytes[start:stop])
    return unaccent(raw.decode('utf-8', 'ignore'))

programs.haiku:
"""Digit written right after the letter o/O, as in an oxygen subscript or an
o-ending word piece: CO2, NO2, PaO2, Y2O3, PO4, boto3, no2. The component
switches on for that digit, strongest for 2 and 3 (CO2, BaCO3, boto3, no2), a
little less for 1 and 4, and weakest for the rest. Everywhere else it is 0."""

READS = ()

# typical activation for a digit after o/O, by digit
STRENGTH = {"2": 6.0, "3": 6.0, "1": 4.0, "4": 4.0}
OTHER_DIGIT = 2.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    value = 0.0
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].rstrip()
        if len(tok) == 1 and tok.isdigit() and prev[-1:] in ("o", "O"):
            value = STRENGTH.get(tok, OTHER_DIGIT)
    return carry, float(value)

