def korean_ending(c, fragmented=False):
    """Unicode cycles through 28 Hangul codas; group their letter families."""
    final = (ord(c) - 0xAC00) % 28
    if final == 0:
        return -0.3 if fragmented else 0.0
    if final in (1, 2, 3, 9, 24):  # velar stop: k
        return -3.3 if fragmented else -1.08
    if final in (11, 14, 17, 18, 26):  # bilabial stop: p
        return -3.2 if fragmented else -0.87
    if final == 21:  # velar nasal: ng
        return -2.1 if fragmented else -0.38
    if final in (4, 5, 6, 8, 10, 12, 13, 15, 16):  # n, m, l
        return -0.7 if fragmented else -0.18
    return -2.1 if fragmented else -0.56  # unreleased t


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
