All later tokens get zero. At a row/document reset, Latin-script tokens
receive a pulse based on English word frequency, capitalization and grammar;
unindented declaration keywords get an extra boost. Spaces, punctuation,
digits, special tokens and other scripts have separate formatting rules.
These rules approximate, rather than memorize, token-specific onset values;
they do not reproduce the small context-dependent activations later on.
"""
import math
import regex
from wordfreq import zipf_frequency

READS = ()

ARTICLES = {'a', 'an', 'the'}
POSSESSIVES = set('my our your his her its their mine ours yours hers theirs'.split())
PREPOSITIONS = set('of to in for with on by at from as into about over after '
                   'before under between through without within against during'.split())
CONJUNCTIONS = set('and or but nor so yet if because although while unless than '
                   'whether since'.split())
AUXILIARIES = set('am is are was were be been being have has had having do does '
                  'did can could will would shall should may might must'.split())
QUESTIONS = set('what who whom whose which when where why how'.split())
DEMONSTRATIVES = {'this', 'that', 'these', 'those'}
MODULE_DECLARATIONS = {'import', 'package'}
FUNCTION_DECLARATIONS = {'def', 'function'}
VARIABLE_DECLARATIONS = {'const', 'let', 'var', 'static'}
ACCESS_MODIFIERS = {'public', 'private', 'protected'}
PRIMITIVE_TYPES = set('int char void bool float double long short unsigned'.split())

SCRIPT_LEVELS = {
    'Han': (2.93, 0.14),
    'Cyrillic': (2.96, -0.60),
    'Greek': (2.53, -0.28),
    'Arabic': (1.67, 0.02),
    'Hebrew': (0.02, 0.02),
    'Devanagari': (0.56, 0.17),
    'Hiragana': (0.41, 0.07),
    'Katakana': (1.12, 0.30),
    'Hangul': (2.62, -0.89),
}


def onset(s):
    w = s.strip()
    if s.startswith('<|') and s.endswith('|>'):
        return 2.99
    if not w:
        if '\n' in s or '\r' in s:
            return 2.47 - 1.14 * min(2, max(0, s.count('\n') - 1))
        if '\t' in s:
            return 5.73
        return -0.40 if len(s) <= 1 else 2.85 + 0.73 * math.log(len(s))
    leading = s[0].isspace()
