    if w.startswith('#'):
        return 7.6 if len(w) == 1 else (5.0 if set(w) == {'#'} else 7.2)
    if regex.search(r'\p{Script=Latin}', w):
        frequency = zipf_frequency(w, 'en')
        value = 2.95 + 0.72 * frequency + 0.53 * max(0, frequency - 5)
        value -= 2.39 * leading
        value += 1.48 * w[0].isupper()
        value -= 2.59 * (w.isupper() and len(w) > 1)
        value -= 1.81 * (len(w) == 1) + 0.77 * (len(w) == 2)
        value += 0.59 * (len(w) >= 8)
        value -= 1.96 * (not w.isalpha()) + 0.15 * (not w.isascii())
        word = w.lower()
