            (ARTICLES, 2.55), (POSSESSIVES, 2.7), (PREPOSITIONS, 0.40),
            (CONJUNCTIONS, -2.54), (AUXILIARIES, -0.79),
            (QUESTIONS, 0.65), (DEMONSTRATIVES, -1.35),
