                (MODULE_DECLARATIONS, 6.9), (FUNCTION_DECLARATIONS, 8.5),
                (VARIABLE_DECLARATIONS, 6.5), (ACCESS_MODIFIERS, 6.5),
                (PRIMITIVE_TYPES, 6.5),
