    if w.startswith(('/*', '<?', '<!')):
        return 5.0
    if w == '[':
        return 3.6
    if w == '<':
        return 4.5
    if w == '(':
        return -0.9 if leading else 1.5
    if w == '\\':
        return 2.7
    if len(w) >= 2 and set(w) == {'-'}:
        return 4.0
    if '\n' in s or '\r' in s:
        return 0.4 if s.count('\n') >= 2 else 2.4
    return -0.25 if len(w) == 1 else 0.5



def step(carry, prefix, upstream):
    first = (len(prefix.document_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    return None, float(onset(prefix.token_strings[-1]) if first else 0.0)

