"""Approximate document-start spelling effects and a few local bursts.

Starts have a negative background, offset by short L-containing fragments,
leading Latin L, spacing, digits, and punctuation. The same estimate is used just
after an end-of-text marker. Elsewhere the main positive rules detect nearby
repeated 1s, 'all the/of', and adjacent L-containing continuation fragments.
These are spelling/context heuristics, not a complete activation model.
"""
from anyascii import anyascii

READS = ()


def initial_value(raw):
    if raw == '<|endoftext|>':
        return -1.94
    if raw.startswith(('<|im_', '<tool', '</tool')):
        return -0.23
    word = raw.strip()
    spelling = anyascii(word)
    value = -0.31 - 0.04 * min(len(spelling), 15)
    value += 0.19 * raw[:1].isspace()
    value += 0.28 * spelling.isdigit() - 0.06 * spelling.isalpha()
    if spelling and not any(c.isalnum() for c in spelling):
        value += 0.17
    if 'l' in word.lower():
        value += 0.39
        if word.isalpha():
            value += 0.65 * (len(word) <= 3)
            value += 0.61 * word.lower().startswith('l')
        else:
            value += 0.08
    value -= 0.05 * word.istitle()
    value += 0.06 * (word.isupper() and len(word) > 1)
    value -= 0.13 * ('\ufffd' in raw)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, two_back = ('', '') if first else carry[1:]
    raw = prefix.token_strings[-1]
    token = anyascii(raw).lower()
    next_carry = (doc, token, previous)
    if first:
        return next_carry, initial_value(raw)
    if previous == '<|endoftext|>':
        return next_carry, 0.16 + 1.33 * initial_value(raw)

    value = -0.004
    digit = len(token) == 1 and token.isdigit()
    if token == '1' and two_back == '1':
        value += 0.38
        if len(previous) == 1 and previous.isdigit():
            value += 0.22
        if previous == '9':
            value -= 0.29
        if any(c in previous for c in '\n\r{}=-'):
            value -= 0.13
    if digit and previous == two_back == '1':
        value += 0.56

    if previous.strip() == 'all':
        if token == ' the':
            value += 0.70
        elif token == ' of':
            value += 0.32
    if two_back.strip() == 'all' and token == ' the':
        value += 0.24

    if not token[:1].isspace():
        if ('l' in token or token == '1') and 'l' in previous:
            value += 0.13 + 0.30 * (len(previous.strip()) <= 3)
        if token.strip().isalpha():
            value += 0.12 * (previous.strip() == 'l' and len(token) <= 3)
            value += 0.11 * (two_back.strip() == 'l')
    return next_carry, value

