FUNC_WORDS = {" the", "The", " of", " and", " a", " to", " in", " on", " that", " for", " as", " with", " at", " I", " my", " will", " or"}
CODE_WORDS = {"//", "#!/", "function", "def", "const", "int"}


def step(carry, prefix, upstream):
    w = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        if w in FUNC_WORDS:
            return None, 0.3
        if w in CODE_WORDS:
            return None, 1.2
    if w in BIG:
        return None, BIG[w]
    if w in NEG_STRONG:
        return None, NEG_STRONG[w]
    if any(k in w for k in MID):
        return None, 1.0
    if any(k in w for k in LOW):
        return None, 0.5
    if any(k in w for k in NEG_MID):
        return None, -0.5
    if any(k in w for k in NEG_WEAK):
        return None, -0.2
    if w == "package":
        return None, -0.3
    return None, 0.0

programs.sol:
"""Estimate negative responses to adjacent closing/opening delimiters.

The main trigger is || in a table row or after an unmatched single bar.
Later separators on that line are weaker, except in wholly empty rows.
Dollar and quote pairs also use earlier openers. Smaller rules cover quoted
field junctions and other crowded punctuation; ordinary text gets zero.
Remember at most 2048 characters of the current line, resetting at document
boundaries and special-token markers.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, previous = '', ''
    else:
        _, line, previous = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    spaced = token[:1].isspace()
    last = previous[-1:]
    value = 0.0
    plain = s.replace('\\', '')

    if '||' in s:
        single_bars = line.replace('||', '').count('|')
        start = line.lstrip()
        table_row = start.startswith('|') and not start.startswith('||')
        if table_row or (single_bars % 2 and not spaced):
            count = min(line.count('||'), 4)
            if not line.replace('|', '').strip():
                count = 0  # A row of empty cells stays a delimiter cluster.
            value = -5.0 / (1 + count) if spaced else (
                -6.0 / (1 + 0.2 * count))
        else:
            value = -0.15 if spaced else -1.2
        if s.startswith('(') or '\n' in token:
            value = 0.0
        elif s.startswith(')') or s.endswith('('):
            value += 0.7
    elif '$$$$' in s:
        value = -5.2
    elif s == '$$' and not spaced and line.replace('$$', '').count('$') % 2:
        value = -4.5
    elif '」「' in s:
        value = -5.6
    elif '"/><' in s:
        value = -0.75
    elif '"<<' in s:
        value = -1.05
    elif '","' in plain or '":"' in plain:
        if not spaced or last.isalnum():
            value = -1.0 if '\\' in s or ',' in s else -0.55
    elif s.count("'") >= 2 and ',' in s:
        value = -0.7
    elif s.count('"') == 2 and s.startswith('""') and not spaced:
        value = -5.5 if last.isalpha() and line.count('"') % 2 else -0.4
    elif s in ('"+"', '"."') and not spaced:
        value = -3.1
    elif s.endswith('\\') and ('"' in s or "'" in s):
        value = -0.15 if s.startswith('\\') else -0.65
    elif "''" in s and not spaced:
        value = -1.2 if last.isalpha() or s.startswith('.') else 0.0
    elif s == '``':
        value = 0.07 if spaced else 0.27
    elif s == '··':
        value = -0.85 if previous == token else -0.1

    if token.startswith('<|') and token.endswith('|>'):
        line = ''
    else:
        line = (line + token).rsplit('\n', 1)[-1][-2048:]
    return (doc, line, token), value

"""An initial-token pulse, continuing through an identical-token opening run.

Its size depends on familiar token classes: digits, whitespace and articles
are weak; words, quotation marks and code declarations are stronger. Leading
spaces and longer word pieces reduce the pulse. Once a different token has
appeared, the prediction is zero. This is only a coarse lexical approximation.
"""
import unicodedata
import regex

READS = ()
ARTICLES = {'a', 'an', 'the'}
PRONOUNS = set(
    'i you he she it we they me him her us them '
    'my your his its our their'.split()
)
PREPOSITIONS = set(
    'of in on at by for from with into onto over under '
    'between through without within about'.split()
)
CONJUNCTIONS = set(
    'and or but nor so yet if because although while whether'.split()
)
AUXILIARIES = set(
    'is are was were am be been being have has had do does did '
    'can could will would shall should may might must'.split()
)
CODE_WORDS = set(
    'package import namespace using include define class struct '
    'public private protected static def function const var let return void'.split()
)


def opening_strength(text):
    s = text.strip()
    space = text.startswith(' ')
    if not s:
        return -0.4 if '\n' in text else 0.2
    if s.isdigit():
        return -0.4
    if text.startswith('<|'):
        return 3.7
    if text == '\\n':
        return 14.5
    if text == '\\t':
        return 21.4
    # Dot leaders and caret dividers can form a whole repeated opening.
    if set(s) == {'·'}:
        return 13.1
    if len(s) > 1 and set(s) == {'^'}:
        return 15.8
    value = 3.9 - 2.2 * space - 2.0 * ('\n' in text)
    if s.isascii() and s.isalpha():
        word = s.lower()
        value += 2.6 - 0.5 * min(len(s), 12)
        value += 3.0 * s[0].isupper() - 2.2 * s.isupper()
        if word in ARTICLES:
            value += -7.2 + 4.5 * space
        if word in PRONOUNS:
            value += 1.2
        if word in PREPOSITIONS:
            value += -4.0 + 0.9 * space
        if word in CONJUNCTIONS:
            value += 0.2 + 0.7 * space
        if word in AUXILIARIES:
            value += 1.4 - 1.6 * space
        if word in CODE_WORDS:
            value += 9.0 - 6.9 * space
    else:
        if '\ufffd' in text:
            value += 2.5
        if regex.search(r'\p{Script=Arabic}|\p{Script=Hangul}', text):
            value += 2.6
        if regex.search(r'\p{Script=Katakana}', text):
            value += 2.0
        if s in {'.', '。'}:
            value -= 3.0
        if any(c in '\"“”‘’' for c in s):
            value += 3.0
        if s.startswith('#'):
            value += 2.0
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, token, True)
    document, first_token, opening_run = carry
    opening_run = opening_run and token == first_token
    value = opening_strength(prefix.token_strings[-1]) if opening_run else 0.0
    return (document, first_token, opening_run), float(value)

"""Approximate a function-declaration and constructor signal.

The largest positive responses mark Rust fn and Python __init__ definitions.
Indentation, a nearby class, modifiers, and double underscores set their
strength. Other declaration keywords get smaller positive values; indented
expect assertions get negative values. Separate spelling responses are negative
for ia, tokens beginning 有关 (concerning), and 令, especially after 夏 or 冬
(summer/winter). Unlisted tokens get zero. These rules omit weaker lexical
responses and approximate, rather than reproduce, contextual magnitudes.
"""
import re

READS = ()
MODIFIERS = {'public', 'private', 'protected', 'static', 'virtual', 'override'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, previous2 = '', '', ''
    else:
        _, tail, previous, previous2 = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    state = (doc, (tail + token)[-256:], token, previous)
    if word == 'ia':
        return state, -0.3
    if word.startswith('有关'):
        return state, -2.0
    if word == '令':
        return state, -3.8 if previous in {'夏', '冬'} else -0.3
    if word not in {'fn', 'def', 'init', '__', 'void', 'boolean',
                    'function', 'func', 'let', 'expect'}:
        return state, 0.0
    value = 0.0
    # Both literal and escaped newlines occur in source-code listings.
    line = re.split(r'\n|\\n', tail)[-1]
    leading = line + token[:len(token) - len(token.lstrip())]
    leading = re.sub(r'^\s*\d+\t', '', leading)
    leading = re.sub(r'^[+-](?=\s)', '', leading)
    indentation = len(leading.expandtabs(4)) if not leading.strip() else -1
    last = previous.strip()
    spaced = token.startswith(' ')
    recent_class = bool(re.search(r'\bclass\s', tail))
    rust = bool(re.search(
        r'\b(?:impl|pub|use)\b|::|->|&mut|\.rs', tail))
    whitespace = previous.isspace() and '\n' not in previous

    if word == 'fn':
        if last == 'pub' or re.search(r'\bpub\([^)]*\)\s*$', line):
            value = 8.0 if previous[:1].isspace() or last != 'pub' else 4.6
        elif last in {'async', 'const', 'unsafe', 'extern'}:
            value = 7.0 if 'pub ' in line else 4.5
        elif indentation >= 0 or whitespace:
            if token.startswith('\t'):
                value = 2.6
            elif spaced:
                value = 4.8 if rust else 2.5
            else:
                value = 2.3
        elif last.endswith('@'):
            value = 2.4
        else:
            value = 0.4
    elif word == 'def':
        if indentation >= 0 or whitespace or token.startswith('\t'):
            if recent_class:
                value = 4.7 if spaced or token.startswith('\t') else 1.1
            elif spaced:
                value = 2.9 if indentation <= 6 else 2.0
            else:
                value = 1.8 if token.startswith('\t') else 0.9
        elif last == 'async':
            value = 1.2
        else:
            value = 0.15 if spaced else 0.4
    elif word == 'init':
        if previous.endswith('__'):
            value = 4.1
            if previous == ' __' and previous2.strip() == 'def':
                value = 9.2 if recent_class else 7.5
            elif previous.endswith('.__'):
                value = 3.5
    elif word == '__' and last == 'def':
        value = 2.2 if recent_class else 1.3
    elif word == 'void':
        if last == 'public':
            value = 2.4 if recent_class else 2.1
        elif last in {'static', 'override'}:
            value = 1.35 if previous[:1].isspace() else 0.45
        elif last in MODIFIERS or indentation >= 0:
            value = 0.4
    elif word == 'boolean' and last in MODIFIERS:
        value = 0.8 if last == 'public' else 0.35
    elif word == 'function':
        if last in MODIFIERS:
            value = 1.8 if recent_class else 1.2
        elif last in {'=', 'async', 'export'}:
            value = 0.85
        elif last == ':':
            value = 0.5
        elif indentation >= 0:
            value = 0.6
    elif word == 'func' and (indentation >= 0 or spaced):
        value = 0.4 if not token.startswith('\t') else 0.15
    elif (word == 'let' and (indentation >= 0 or whitespace)
          and token[:1].isspace()):
        value = 1.3 if rust else 0.3
    elif word == 'expect':
        if indentation > 0 or whitespace:
            value = -1.9 if spaced else -1.0
        elif last == ':':
            value = -1.0
    return state, value

programs.haiku:
"""Function-definition keywords.

The component fires on the word that opens a function or method definition in source code,
i.e. where the model expects the function's name next:
  - Rust `fn`: strongest after `pub` (a method), weaker at the start of a line;
  - Python `def` at the start of a line (usually an indented method);
  - the `__` and `init` of `__init__`;
  - Java `void` after an access modifier (`public void`);
  - JS/PHP `function` after an access modifier (`public function`).
Rust `let` at the start of a line gets a small value. Everything else is 0.
"""

READS = ()
ACCESS = ("public", "private", "protected", "static")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    word = toks[-1].strip()
    prev = toks[-2] if len(toks) > 1 else ""
    p = prev.strip()
    line_start = p == "" or prev.endswith("\n")

    if word == "fn":
        if p in ("pub", "async") or p.endswith("pub"):
            return carry, 8.0
        return carry, 3.5 if line_start else 2.0
    if word == "def":
        return carry, 3.5 if line_start else 0.0
    if word == "__" and p == "def":
        return carry, 1.8
    if word == "init" and p.endswith("__"):
        return carry, 6.0
    if word == "void" and p in ACCESS:
        return carry, 1.8
    if word == "function" and p in ACCESS:
        return carry, 1.4
    if word == "let" and line_start:
        return carry, 1.0
    return carry, 0.0

programs.sol:
"""Approximate a sparse punctuation and writing-glyph response.

Opening double quotes are mostly negative in Han, kana or Thai contexts
and at document starts. Line starts lower them further. Nearby quotes soften
this response; a Chinese speech verb before a comma-quote can reverse it.
These rules approximate the punctuation contrasts observed in training.
A few orthographic signals (middle dots, nonbreaking spaces and drawing
characters) receive independent rules. Document-start baselines also use
spelling and English word frequency. Most lexical variation is left unmodeled.
"""
import regex
from wordfreq import zipf_frequency

READS = ()
SPEECH_VERBS = (
    '说', '說', '道', '问', '問', '答', '表示', '指出',
    '强调', '強調', '介绍', '介紹', '回忆', '回憶', '称', '稱',
)
ASIAN = regex.compile(
    r'[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}'
    r'\p{Script=Thai}]'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, history, tail = 0, (), b''
    else:
        _, position, history, tail = carry
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    before = ''.join(history)
    asian = bool(ASIAN.search(before[-24:]))
    recent = sum(before[-40:].count(q) for q in '“”')
    speech = before.rstrip().endswith(SPEECH_VERBS)
    speech = speech and not before.rstrip().endswith(('来说', '來說'))
    value = 0.0

    if token in ('“', ' “', '，“', '。“', '.“', '、“', '：“'):
        if token == '“':
            value = -0.29 if asian else 0.11
        elif token == ' “':
            value = -0.55 if asian else 0.04
        elif token == '，“':
            value = -0.64 + 0.78 * speech
        elif token in ('。“', '.“'):
            value = -0.78 if asian else 0.0
        elif token == '、“':
            value = -0.64
        else:
            value = -0.13
        value += 0.21 * speech + 0.01 * min(recent, 4)
        value -= 0.19 * before.endswith('\n') + 0.26 / (position + 1)
        if position == 0:
            value = -2.55 if token == '“' else -0.94
    elif token in ('"', ' "'):
        value = -0.18 if asian else -0.01
        if position == 0:
            value = -1.46 if token == '"' else -0.59
    elif token.startswith('"') and position == 0:
        value = -0.9
    elif token == '\\"' and position == 0:
        value = -0.78
    elif token == "'":
        value = -0.009
    elif token == '–':
        value = -0.4 if asian else 0.1
    elif token and set(token) == {'\xa0'}:
        value = min(0.25, 0.067 * len(token) - 0.035)
    elif token == '·':
        value = -0.04
    elif token == '··':
        value = 0.95
    elif raw == b'\xc2':
        value = -0.18  # An unfinished Latin-1 UTF-8 character.
    elif token == ' *' and position == 0:
        value = 1.85

    if position == 0 and value == 0.0:
        word = token.strip()
        if word.isdigit():
            value = 0.14
        elif word.isascii() and word.isalpha():
            value = (0.122 - 0.066 * token.startswith(' ')
                     + 0.035 * word.istitle() - 0.014 * word.isupper()
                     + 0.011 * min(10, len(word))
                     - 0.028 * zipf_frequency(word.lower(), 'en'))
        elif token == '#':
            value = 0.70
        elif token == '-':
            value = -0.22
        elif token == '.':
            value = 0.065

    # Match completed characters even when UTF-8 was split between tokens.
    ending = tail + raw
    for character, strength in (('绘', 2.0), ('絵', 1.35), ('描', 0.49)):
        if len(raw) <= 3 and ending.endswith(character.encode('utf-8')):
            value = strength
    carry = (doc, position + 1, (history + (token,))[-12:], ending[-3:])
    return carry, float(value)

"""Detect written 'back/return' in Chinese, with a weaker Japanese response.

回 itself is strongest, especially without nearby kana. Several return
compounds are weaker; 回答 ('answer') is not treated as a return signal.
Entering/progress words and the Korean syllable 회 are weaker;
회 is stronger as a repetition counter after a number.
The completion particle 了 can retain the preceding 回 signal. A small
word-shape-based offset marks document starts; state resets there.
