        if word and word[0].isalpha():
            if regex.search(r'\p{Script=Han}', word):
                value = 0.0
            else:
                value = 0.18 if token.startswith(' ') else 0.37
        else:
            value = 0.15

    if word == '回':
        value = -4.2 if japanese else -7.4
        if japanese and previous.endswith('見'):  # 'look around'
            value = -2.0
    elif word == '迴':
        value = -3.5 if japanese else -5.9
    elif '回' in word or '進' in word or '进' in word:
        simple = SIMPLIFY.convert(word)
        if simple == '回去':
            value = -4.1
        elif simple in ('回来', '回家', '来回', '退回', '收回'):
            value = -3.3
        elif simple in ('回到', '回到了', '回到家', '轮回', '回头', '回国'):
            value = -1.7
        elif simple in ('回归', '回收', '返回'):
            value = -0.7
        elif simple == '进':
            value = -0.2 if japanese else -1.4
            if previous.endswith(('推', '先', '递', '共', '后', '後')):
                value = -0.4
        elif simple in ('进了', '走进'):
            value = -1.2
        elif simple in ('推进', '前进', '引进', '放进'):
            value = -0.6
    elif word in ('插入', '录入', '錄入'):
        value = -1.1
    elif word == '회':
        value = -1.1 if text.rstrip()[-1:].isnumeric() else -0.5
    elif word == '了' and previous in ('回', '迴'):
        value = 0.45 * last_value

    return (doc, (text + token)[-100:], word, value), value

"""Coarse spelling-context approximation of this component.

After ignoring case and accents, match short continuations of t-bearing
word pieces: e/r-like pieces tend negative; selected ent/ens pieces tend
positive. Greek tau-vowel continuations are positive too. Two preceding
pieces are kept, with a reset at document boundaries. Unmatched tokens
get zero. These rules capture only a small part of the measured behavior;
they do not reproduce the component's token-specific variation.
"""
import unicodedata
from functools import lru_cache

READS = ()


@lru_cache(maxsize=8192)
def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def spelling(s, p, q):
    if s.startswith('η') and p.strip() == 'τ':
        return 1.57 if p[:1].isspace() else 0.58
    if s == 'ν' and p == 'η' and q.strip() == 'τ':
        return 1.19
    if s.startswith('ε') and p.strip() == 'τ':
        return 1.19
    if s == 'λ' and p == 'ε' and q.strip() == 'τ':
        return 2.41
    if not s or s[:1].isspace():
        return 0.0
    if s == 'eter':
        return -0.93
    if p.endswith(('t', 'tion', 'tern', 'ter', 'tain')):
        if s.startswith('er') and 'o' not in s:
            return -1.42 if s.startswith('ern') else -0.55
        if s.startswith('ier'):
            return -0.74
        if s.startswith(('ent', 'ens')) and 'l' not in s:
            return 0.61
    if 't' in p and s.startswith('e'):
        if p.endswith(('ant', 'int')) and len(s) <= 3:
            return 0.19
        if p.endswith('te') and len(s) <= 3:
            return -0.78
        if p.endswith('et') and len(s) <= 3:
            return -0.58
        if p.endswith(('ent', 'rt', 'st')) and len(s) <= 3:
            return -0.15
        return -0.05
    if s.startswith('re') and 't' in p:
        return -0.07
    if s.startswith('te') and p.endswith('e'):
        return -0.32
    if s == 'ing' and p.endswith('ter') and 's' not in p:
        return -0.58
    if s.startswith('ер') and 'т' in p:
        return -0.74
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    p, q = ('', '') if reset else carry[1:]
    s = plain(prefix.token_strings[-1])
    return (doc, s, p), spelling(s, p, q)

"""A sparse approximation of document-opening and formatting responses.

Large responses are reserved for recognizable code or question headers, boundary
markers, initial formatting, and the colon of an opening `Title:`. An unbroken
initial run retains its opening response. Elsewhere only coarse punctuation
biases are predicted. Long bare carriage-return runs become negative once they
outweigh preceding text. Most lexical variation is not modeled.
"""
from math import exp

READS = ()


def opening(text):
    if text == 'namespace':
        return 1.875
    if text in {'class', 'def'}:
        return 0.88
    if text in {'import', 'package'}:
        return -0.31
    if text in {'Question', 'Q'}:
        return 0.77
    if text in {'The', 'A'}:
        return 0.40
    if text == 'Title':
        return -0.366
    if text == '<|im_start|>':
        return -0.250
    if text == '<|endoftext|>':
        return -0.711
    if text == '//\n':
        return -8.252
    if text == '\r':
        return -4.614
    if text == '\t':
        return 0.827
    if text == '··':
        return -0.486
    return 0.06


def background(text):
    if '"' in text or "'" in text or '`' in text:
        return -0.012
    stripped = text.strip()
    if stripped and not any(c.isalnum() for c in stripped):
        return 0.009 if text.startswith(' ') else -0.003
    return 0.006


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    fresh = carry is None or carry[0] != doc
    if fresh:
        position, previous, same, run = 0, text, True, 0
    else:
        _, position, previous, same, run = carry
        position += 1
        same = same and prefix.token_ids[-1] == prefix.token_ids[-2]
    run = run + 1 if text == '\r' else 0
    value = opening(text) if same else background(text)
    if run and not same:
        # More preceding text delays the negative return-run response.
        preceding = position + 1 - run
        allowance = 30 * (1 - exp(-(preceding - 1) / 5))
        threshold = 0.35 + 0.65 * preceding + allowance
        dominance = max(0.0, (run - threshold) / (run + threshold))
        value = 0.07 - 4.4 * dominance
    if position == 1 and previous == 'Title' and text == ':':
        value = -3.031
    return (doc, position, text, same, run), value

"""Approximate a mostly whitespace-and-formatting response.

The main signal is negative on a single space continuing a run of spaces,
stronger for short indentation than for in-line alignment. Initial spaces
behave differently. Other rules recognize GitHub hostnames, git diff
headers, paired backslashes (positive for TeX line breaks, negative for
escaped code), a code delimiter after nonbreaking spaces, and middle-dot
fill. Everything else is zero; small lexical fluctuations are omitted.
Only a short suffix and simple line/document state are carried forward.
"""
import re

READS = ()
MATH_COMMAND = re.compile(r'\\(?:frac|text|begin|left|right|hfill|lim|sum|delta)\b')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, blank_line, tail, age = '', True, '', 0
    else:
        _, previous, blank_line, tail, age = carry
    token = prefix.token_strings[-1]
    value = 0.0

    if token == ' ':
        if first or (age == 1 and previous == ' '):
            value = 1.944
        elif previous and not previous.strip(' '):
            width = len(previous)
            if width == 1:
                value = -0.82 if blank_line else -0.18
            elif width <= 4:
                value = -1.20 - 0.13 * width
                if not blank_line:
                    value += 0.33
            else:
                value = -1.25
            if age == 1:
                value *= 1.7
        else:
            value = 0.005
    elif token == '.com' and tail.endswith('github'):
        if not tail.endswith('.github'):
            if previous.startswith('"'):
                value = 3.15
            else:
                value = 2.9 if tail.endswith('://github') else 2.2
    elif token == 'git' and tail.endswith('diff --'):
        value = 0.82
    elif token == ' -' and previous == '@@':
        value = 1.46
    elif token.endswith('\\\\'):
        math = bool(MATH_COMMAND.search(tail))
        escaped_code = '\\n' in tail or '\\"' in tail
        if math or (token == ' \\\\' and not escaped_code):
            value = 1.12
        else:
            value = -0.4 if token.endswith('\\\\\\\\') else -0.75
    elif token == '``' and previous.endswith('\u00a0'):
        value = -0.66
    elif token == '··':
        value = 1.145

    if '\n' in token or '\r' in token:
        blank_line = not token.replace('\r', '\n').rsplit('\n', 1)[-1].strip()
    else:
        blank_line = blank_line and not token.strip()
    state = (doc, token, blank_line, (tail + token)[-96:], age + 1)
    return state, value

"""Detect in-line indentation: whitespace after printed line numbers, literal
backslash-n, and comment/diff prefixes. Real newlines and ordinary spaces are
quiet. Wider indentation is more negative. A small extra rule recognizes the
suffix of GitHub web/content hostnames. No lexical code-type lookup is used.
"""
import math
import re

READS = ()


def indentation_value(s, line):
    if '\n' in s or '\r' in s:
        return 0.0
    numbered = bool(re.fullmatch(r'\s*(?:--?>\s*)?\d+', line))
    if s.startswith('\t') and numbered:
        tabs = len(s) - len(s.lstrip('\t'))
        spaces = len(s) - len(s.lstrip('\t ')) - tabs
        if tabs > 1:
            return -2.1
        if spaces:
            return -min(2.05, 0.95 + 0.24 * math.log2(spaces + 1))
        if s == '\t':
            return -0.9
        return -1.1 if s[1:] in ('import', 'from') else -0.5
    if s.startswith('\t') and line.endswith(('//', '-')):
        return -1.3
    if s == '\\t':
        return -0.18
    if s and not s.strip(' '):
        n = len(s)
        if line.endswith('\\n'):
            return -min(1.85, 0.72 + 0.5 * math.log2(n))
        if n > 1:
            if numbered:
                return -min(2.4, 1.3 + 0.12 * n)
            if line.endswith(('//', '#')):
                return -1.0
            if line.endswith('+') or (line.endswith('-') and n >= 3):
                return -1.2
            if line.endswith(('/*', '*/')):
                return -1.6
            if re.fullmatch(r'\s*[\'\"]', line):
                return -1.7
            if re.search(r'\d+:$', line) and n >= 3:
                return -1.5
            if re.fullmatch(r'\s*\d* *[|│]', line):
                return -1.4
            if 16 < n < 64 and line.endswith(' '):
                return -1.05
    if s and not s.strip('\xa0'):
        if numbered:
            return -1.65
        if '`' in line:
            if len(s) >= 3:
                return -1.5
            if len(s) == 1:
                return -1.3 if line.endswith('\xa0' * 3) else -0.3
    if s == '``' and line.endswith('\xa0'):
        return -1.25
    return 0.0


def secondary_value(s, line):
    if s == '.com' and re.search(
        r'(?:^|[^\w.])(?:github|raw\.githubusercontent)$', line.lower()
    ):
        return -1.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    line = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = indentation_value(s, line) or secondary_value(s, line)
    line = (line + s).rsplit('\n', 1)[-1][-100:]
    return (doc, line), value

"""Local rules for year prefixes, code layout, and quoted/negative phrases.

The main positive cue is the third digit of a recent year. The main negative
cue is indentation after a visible code gutter or an escaped newline, not
ordinary indentation at the start of a line. Smaller rules cover object-value
quotes and negation. Initial repeated digits 4--8 also receive a positive
value. These are approximate text cues, not a complete lexical model.
"""
import re

READS = ()

# Numbered listings, grep output, and comment-style line-number gutters.
NUMBER_GUTTER = r'(?:^|\n)( *)[0-9]+$'
MARKED_GUTTER = r'(?:^|\n) *(?:[0-9]+:|/\* *[0-9]+ *\*/)$'
DIFF_OR_STRING = r'(?:^|\n)[ \t]*[-+\'\"]$'
DEEP_GUTTER = r'(?:^|\n) *[0-9]+\t[ \t]*$'
AUXILIARY = r'\b(?:could|should|would|did|does|do|is|was|are|were|have|has|had)$'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if tail else ''
    value = -0.13 if not tail else 0.0

    # An initial run of identical middle-valued decimal digits.
    if len(token) == 1 and '4' <= token <= '8':
        if not tail or tail == token * len(tail):
            value = 1.27

    # At the third digit, a year prefix identifies its decade.
    match = re.search(r'[0-9]+$', tail)
    number = match.group() if match else ''
    if len(number) == 2 and len(token) == 1 and token in '0123456789':
        decade = int(token)
        if number == '20':
            value = {0: 0.6, 1: 1.0, 2: 0.73}.get(decade, 0.0)
        elif number == '19':
            value = min(0.98, 0.13 * decade - 0.08)
        elif number == '18' and decade >= 7:
            value = 0.08
        if len(tail) > 2 and not tail[-3].isspace() and tail[-3] != '(':
            value *= 0.75

    gutter = re.search(NUMBER_GUTTER, tail)
    marked = re.search(MARKED_GUTTER, tail)
    if token.startswith('\t') and gutter and not token.isspace():
        value = -0.3
    if token and token.isspace() and '\n' not in token and '\r' not in token:
        if (gutter or marked) and token.startswith('\t'):
            value = -1.1 if token.count('\t') >= 2 else -0.74
            if token.count(' '):
                value = -0.85 - 0.008 * token.count(' ')
        elif marked or (gutter and len(gutter[1]) >= 3 and len(token) >= 3):
            value = -0.85
        elif len(token) >= 24 and re.search(DEEP_GUTTER, tail):
            value = -0.6
        elif len(token) >= 3 and re.search(DIFF_OR_STRING, tail):
            value = -0.7
        elif tail.endswith('\\n'):
            value = -0.75 if previous == 'n' else -0.45
            if len(token) == 1:
                value -= 0.15
            elif len(token) == 2:
                value += 0.2
        elif re.search(r'(?:\n[^\n]*[|│]|//|#|\t \*)$', tail):
            if len(token) >= 3:
                value = -0.4
        elif (token.strip('\xa0') == '' and len(token) >= 3
              and ('`' in tail[-8:] or tail.endswith('\xa0'))):
            value = -0.65
        elif token == ' ' and tail.endswith('\n'):
            value = -0.12
    if token == '``' and tail.endswith('\xa0'):
        value = -0.55
    if len(token) >= 2 and token.strip('·') == '':
        value = -0.65
    if token == 'git' and tail.endswith('diff --'):
        value = 0.7

    # Object values, including nested escaped quotes.
    if token in (' "', " '") and tail.rstrip().endswith(':'):
        key = re.search(r'([A-Za-z_]+)["\']?:$', tail)
        field = key[1] if key else ''
        value = 0.07
        if field in ('command', 'action', 'method'):
            value = 0.4
        elif field == 'type':
            value = 0.78
    if token in ('\\"', '\\"\\') and tail.endswith('\\\\'):
        value = 0.7
    if token == '":':
        value = 0.25 if tail.endswith('name') else 0.12

    if token == ' pas' and re.search(r'\b(?:ne\b|n[’\'])', tail[-60:], re.I):
        value = 0.95
    if token == 'nt' and re.search(AUXILIARY, tail, re.I):
        value = 1.0
    if token == ' not':
        value = 0.08
    return (doc, (tail + token)[-120:]), value

"""Approximate a COME/COM-like spelling response.

COME inflections have the main negative response, weaker after perfect
auxiliaries or when COMING follows a determiner. Function-word votes distinguish
English COME from Romance-language COME. Secondary rules cover short nasal
syllables split after C/K, CUM, ice cream, cones/corn, and the character 梅
(plum). EC-initialisms and GOING have positive responses. Other tokens
are zero. These are surface rules, not a claim that the senses are equivalent.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()
ENGLISH = frozenset('''the and of to is it with for that are was be we you they
this not have will would can has from by but which your our their'''.split())
ROMANCE = frozenset('''il lo gli le della delle che è sono non per dei degli
nella anche così el la las los que con de del se para uma um da do na em
mi ti si ci vi di su'''.split())
PERFECT = frozenset(('have', 'has', 'had', "'ve", '’ve', "'d", '’d'))
MODAL = frozenset('will would should shall could can must may might'.split())
DETERMINER = frozenset('the a an this that these those its their our my your'.split())


@lru_cache(maxsize=65536)
def roman(text):
    return anyascii(text).lower()


def advance(carry, s, doc):
    new_document = carry is None or carry[0] != doc
    if new_document:
        english = romance = 0.0
        previous = fragment = ''
    else:
        _, english, romance, previous, fragment = carry
    w = s.strip().lower()
    english *= 0.97
    romance *= 0.97
    if s[:1].isspace() or new_document:
        english += w in ENGLISH
        romance += w in ROMANCE
    foreign = romance > english + 1
    prev = previous.strip().lower()
    continuation = bool(fragment) and not s[:1].isspace()
    value = 0.0

    joined = (fragment + s).lower() if continuation else ''
    derived = re.fullmatch(r'(be|over|out|in)com(e|es|ing)', joined)
    if derived:
        value = 0.0
    elif w in ('come', 'comes', 'came', 'coming'):
        if continuation and fragment.lower() in ('be', 'over', 'out', 'in'):
            value = 0.0  # become, overcome, outcome, income are different words
        elif foreign:
            value = -1.3 if s.strip()[:1].isupper() else 0.0
        elif w == 'come':
            if s.strip()[:1].isupper():
                value = -6.5
            elif prev in PERFECT:
                value = -2.6
            elif prev in ('that', 'which', 'it', 'they'):
                value = -6.0
            elif prev == 'to' or prev in MODAL:
                value = -4.2
            else:
                value = -4.8
        elif w == 'comes':
            value = -4.0
        elif w == 'came':
            value = -2.1 if prev in ('i', 'we', 'you') else -2.9
            if prev in ('that', 'which'):
                value = -3.8
        else:
            value = -1.5 if prev in DETERMINER else -2.9
    elif w in ('cum', 'kum'):
        value = -4.9 if w == 'cum' else -3.2
    elif w == 'cream':
        value = -4.3 if prev == 'ice' else -0.8
    elif w in ('cone', 'cones'):
        value = -9.0 if fragment.lower() == 'pine' else -2.5
    elif w == 'corn':
        value = -1.1
    elif w == 'cm':
        value = -1.7 if s.strip().isupper() else -0.6
    elif w == 'com':
        value = -0.2
    elif s == '梅':
        value = -4.5
    elif w == 'going':
        value = 0.4
    elif continuation:
        p, t = roman(previous), roman(s)
        if (p.endswith('com') and s.isascii()
                and t in ('e', 'es', 'ed', 'er', 'ing')):
            value = -7.0
        elif re.search(r'[ck]$', p):
            if t in ('um', 'me', 'ome', 'eme'):
                value = -4.0
            elif t in ('om', 'omen', 'orm', 'ane', 'one', 'ama'):
                value = -2.5
            elif (s == 'M' and previous.strip().isupper()
                    and p.endswith('c')):
                value = -4.2
            elif t == 'm':
                value = -2.5 if p.endswith('c') else -0.4
            elif t == 'omo':
                value = -1.5
            elif t == 'ma':
                value = -0.5
            elif (previous.strip().endswith('EC')
                    and s.isascii() and s.isalpha()):
                value = 3.0
            elif (p.strip() == 'ec' or p.endswith('_ec')) and t == 's':
                value = 4.5
        elif (re.search(r'[ck][aeiou]$', p)
                and t in ('m', 'ma', 'me', 'mi', 'mu')):
            value = -3.0 if not previous.isascii() else -1.0
        elif prev == 'e' and s.startswith('C') and s.isupper() and len(s) <= 3:
            value = 2.8
        if s and 'CYRILLIC' in unicodedata.name(s[0], ''):
            value *= 0.25

    # Remember an unfinished word, rather than repeatedly scanning the prefix.
    match = re.search(r'\w+$', s)
    tail = match.group() if match else ''
    if tail and match.start() == 0:
        tail = (fragment + tail)[-24:]
    return (doc, english, romance, s, tail), value


def step(carry, prefix, upstream):
    return advance(carry, prefix.token_strings[-1], prefix.document_ids[-1])
